1	// Personal Cyrus API keys (r39). A key is "cyk_" + 8-char public prefix + "_" + 40 random base62 characters.
2	// Only sha256(key) is stored; the plain key is returned once, at creation. Scopes are a subset of the API v1 scopes
3	// that a customer may hold (never admin). Store behind an interface so tests and a standalone Cyrus can swap it.
4	import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
5	import { SCOPES, type Scope } from "../api/v1/scopes";
6	
7	/** What a personal key may carry: everything in v1 except staff scopes. */
8	export const PERSONAL_SCOPES = SCOPES.filter((s) => s !== "admin:read") as Exclude<Scope, "admin:read">[];
9	export type PersonalScope = (typeof PERSONAL_SCOPES)[number];
10	export const SCOPE_LABEL: Record<PersonalScope, string> = {
11	  "projects:read": "Read projects", "projects:write": "Change projects", "builds:read": "Read builds", "builds:write": "Start builds (spends tokens)",
12	  "installs:read": "Read installs", "installs:write": "Install to servers", "catalog:read": "Read the catalog", "config:write": "Change mod config",
13	  "library:write": "Contribute to the library", "mods:read": "Read mod pages", "account:read": "Read account and tokens", "webhooks:manage": "Manage webhooks",
14	};
15	export const MAX_ACTIVE_KEYS = 10;
16	export const KEY_NAME_MAX = 48;
17	const KEY_RE = /^cyk_([A-Za-z0-9]{8})_([A-Za-z0-9]{40})$/;
18	
19	export type ApiKeyRow = { id: string; userId: string; name: string; prefix: string; sha256: string; scopes: string[]; createdAt: Date; lastUsedAt: Date | null; expiresAt: Date | null; revokedAt: Date | null };
20	export type ApiKeyView = { id: string; name: string; prefix: string; scopes: PersonalScope[]; createdAt: string; lastUsedAt: string | null; expiresAt: string | null; revokedAt: string | null; active: boolean };
21	
22	export interface ApiKeyStore {
23	  listForUser(userId: string): Promise<ApiKeyRow[]>;
24	  insert(row: Omit<ApiKeyRow, "id" | "createdAt" | "lastUsedAt" | "revokedAt">): Promise<ApiKeyRow>;
25	  /** Revoke only if the key belongs to userId; returns false otherwise (never reveals another user's key). */
26	  revoke(userId: string, id: string, at: Date): Promise<boolean>;
27	  bySha(sha256: string): Promise<ApiKeyRow | null>;
28	  touch(id: string, at: Date): Promise<void>;
29	}
30	
31	const B62 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
32	function base62(n: number): string {
33	  let out = "";
34	  while (out.length < n) { for (const b of randomBytes(n * 2)) { if (b < 248 && out.length < n) out += B62[b % 62]; } }
35	  return out;
36	}
37	export const sha256Hex = (s: string) => createHash("sha256").update(s, "utf8").digest("hex");
38	
39	export function newKeyMaterial(): { key: string; prefix: string; sha256: string } {
40	  const prefix = base62(8), secret = base62(40), key = `cyk_${prefix}_${secret}`;
41	  return { key, prefix, sha256: sha256Hex(key) };
42	}
43	
44	export function parseScopes(raw: unknown): { ok: true; scopes: PersonalScope[] } | { ok: false; error: string } {
45	  const arr = Array.isArray(raw) ? raw : typeof raw === "string" ? [raw] : [];
46	  const out = [...new Set(arr.map(String))];
47	  if (!out.length) return { ok: false, error: "Pick at least one permission." };
48	  const bad = out.find((s) => !(PERSONAL_SCOPES as readonly string[]).includes(s));
49	  if (bad) return { ok: false, error: `Unknown permission: ${bad.slice(0, 40)}` };
50	  return { ok: true, scopes: PERSONAL_SCOPES.filter((s) => out.includes(s)) };
51	}
52	
53	export function parseKeyName(raw: unknown): { ok: true; name: string } | { ok: false; error: string } {
54	  const n = String(raw ?? "").replace(/[\u0000-\u001f\u007f]/g, "").trim();
55	  if (!n) return { ok: false, error: "Give the key a name." };
56	  if (n.length > KEY_NAME_MAX) return { ok: false, error: `Keep the name under ${KEY_NAME_MAX} characters.` };
57	  return { ok: true, name: n };
58	}
59	
60	const EXPIRY_DAYS = [0, 30, 90, 365] as const;
61	export function parseExpiry(raw: unknown, now: Date): { ok: true; at: Date | null } | { ok: false; error: string } {
62	  const d = Number(raw ?? 90);
63	  if (!(EXPIRY_DAYS as readonly number[]).includes(d)) return { ok: false, error: "Pick an expiry." };
64	  return { ok: true, at: d === 0 ? null : new Date(now.getTime() + d * 86_400_000) };
65	}
66	
67	export const isActive = (r: Pick<ApiKeyRow, "revokedAt" | "expiresAt">, now: Date) => !r.revokedAt && (!r.expiresAt || r.expiresAt > now);
68	
69	export function toView(r: ApiKeyRow, now: Date): ApiKeyView {
70	  return {
71	    id: r.id, name: r.name, prefix: r.prefix, scopes: r.scopes.filter((s): s is PersonalScope => (PERSONAL_SCOPES as readonly string[]).includes(s)),
72	    createdAt: r.createdAt.toISOString(), lastUsedAt: r.lastUsedAt?.toISOString() ?? null, expiresAt: r.expiresAt?.toISOString() ?? null,
73	    revokedAt: r.revokedAt?.toISOString() ?? null, active: isActive(r, now),
74	  };
75	}
76	
77	export async function createKey(store: ApiKeyStore, userId: string, input: { name: unknown; scopes: unknown; expiryDays?: unknown }, now = new Date()):
78	  Promise<{ ok: true; key: string; view: ApiKeyView } | { ok: false; error: string }> {
79	  const name = parseKeyName(input.name); if (!name.ok) return name;
80	  const scopes = parseScopes(input.scopes); if (!scopes.ok) return scopes;
81	  const exp = parseExpiry(input.expiryDays, now); if (!exp.ok) return exp;
82	  const rows = await store.listForUser(userId);
83	  if (rows.filter((r) => isActive(r, now)).length >= MAX_ACTIVE_KEYS) return { ok: false, error: `You can have ${MAX_ACTIVE_KEYS} active keys. Revoke one first.` };
84	  const m = newKeyMaterial();
85	  const row = await store.insert({ userId, name: name.name, prefix: m.prefix, sha256: m.sha256, scopes: scopes.scopes, expiresAt: exp.at });
86	  return { ok: true, key: m.key, view: toView(row, now) };
87	}
88	
89	/** Resolve a presented key to its owner + scopes. Fails closed on anything malformed, revoked, expired or unknown. */
90	export async function verifyKey(store: ApiKeyStore, presented: string, now = new Date()): Promise<{ userId: string; keyId: string; scopes: PersonalScope[] } | null> {
91	  const m = KEY_RE.exec(String(presented ?? "").trim());
92	  if (!m) return null;
93	  const sha = sha256Hex(m[0]);
94	  const row = await store.bySha(sha).catch(() => null);
95	  if (!row || !isActive(row, now)) return null;
96	  const a = Buffer.from(row.sha256, "hex"), b = Buffer.from(sha, "hex");
97	  if (a.length !== b.length || !timingSafeEqual(a, b) || row.prefix !== m[1]) return null;
98	  await store.touch(row.id, now).catch(() => {});
99	  return { userId: row.userId, keyId: row.id, scopes: toView(row, now).scopes };
100	}
101	
102	/** In-memory store (tests, previews). */
103	export function memoryKeyStore(): ApiKeyStore & { rows: ApiKeyRow[] } {
104	  const rows: ApiKeyRow[] = []; let n = 0;
105	  return {
106	    rows,
107	    async listForUser(u) { return rows.filter((r) => r.userId === u).sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()); },
108	    async insert(r) { const row: ApiKeyRow = { ...r, id: `k${++n}`, createdAt: new Date(), lastUsedAt: null, revokedAt: null }; rows.push(row); return row; },
109	    async revoke(u, id, at) { const r = rows.find((x) => x.id === id && x.userId === u && !x.revokedAt); if (!r) return false; r.revokedAt = at; return true; },
110	    async bySha(s) { return rows.find((r) => r.sha256 === s) ?? null; },
111	    async touch(id, at) { const r = rows.find((x) => x.id === id); if (r) r.lastUsedAt = at; },
112	  };
113	}
114	// Prisma-backed stores for the customer app (r39), through the Cyrus db door (host seam). SERVER ONLY.
115	import { cyrusDb } from "../db";
116	import type { ApiKeyStore } from "./apikeys";
117	import type { DataRequestStore } from "./data-requests";
118	
119	export const prismaKeyStore: ApiKeyStore = {
120	  listForUser: (userId) => cyrusDb.cyrusPersonalApiKey.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 100 }),
121	  insert: (r) => cyrusDb.cyrusPersonalApiKey.create({ data: r }),
122	  async revoke(userId, id, at) { const n = await cyrusDb.cyrusPersonalApiKey.updateMany({ where: { id, userId, revokedAt: null }, data: { revokedAt: at } }); return n.count > 0; },
123	  bySha: (sha256) => cyrusDb.cyrusPersonalApiKey.findUnique({ where: { sha256 } }),
124	  async touch(id, at) { await cyrusDb.cyrusPersonalApiKey.update({ where: { id }, data: { lastUsedAt: at } }); },
125	};
126	
127	export const prismaDataStore: DataRequestStore = {
128	  listForUser: (userId) => cyrusDb.cyrusDataRequest.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 50 }),
129	  insert: (r) => cyrusDb.cyrusDataRequest.create({ data: r }),
130	  async cancel(userId, id) { const n = await cyrusDb.cyrusDataRequest.updateMany({ where: { id, userId, status: "requested" }, data: { status: "cancelled" } }); return n.count > 0; },
131	};
132	// Cyrus API v1: the framework-free handlers (Request -> Response) of the LIVE operations in ./openapi.ts. Reads here; writes (phase 2) in ./writes.ts.
133	// app/api/cyrus/v1/** are one-line wrappers with v1Deps() (./deps.ts); tests pass fakes. Every request:
134	//   flag (off = 404, as if the route did not exist) -> config sane (else 503) -> service token (401) -> scopes (403)
135	//   -> rate limit per key (429) -> subject assertion when the operation is per-user (400/401) -> handler.
136	// Objects that are not the subject's answer 404, exactly like unknown ones. Errors: {error:{code,message,issues?,requestId}}.
137	// HOST SEAM: no Nxeon imports (data comes through V1Deps).
138	import { randomBytes } from "node:crypto";
139	import { access as catalogAccess } from "../../library/v2/tools";
140	import { CATALOG_KINDS, catalogRef, type CatalogEntry, type CatalogKind } from "../../library/v2/entry";
141	import type { CatalogIndex } from "../../library/v2/retrieval";
142	import { API_VERSION, type ApiIssue } from "./schemas";
143	import { BadInput, fail, issue, iso, send, type Ctx } from "./respond";
144	import { BUILD_ID_PATTERN, ENTRY_ID_PATTERN, OPERATIONS, PROJECT_ID_PATTERN, type Operation } from "./openapi";
145	import type { ApiKey, ApiV1Config } from "./config";
146	import { isWriteOperation, runWrite, type V1WriteDeps, type WriteOperationId } from "./writes";
147	import { parseServiceToken, safeEqual, sha256Hex, verifySubjectAssertion, type ReplayCache } from "./signing";
148	
149	export type LiveOperationId = "getHealth" | "listProjects" | "getProject" | "getBuild" | "searchCatalog" | "getCatalogEntry";
150	
151	export type ProjectRow = { id: string; userId: string; game: string; namespace: string; title: string | null; rootBuildId: string | null; headRevisionId: string | null; lastPassingRevisionId: string | null; revisionCount: number; createdAt: Date; updatedAt: Date };
152	export type RevisionRow = { id: string; projectId: string; seq: number; kind: string; status: string; message: string | null; modBuildId: string | null; manifest: unknown; spec: unknown; createdAt: Date };
153	export type BuildRow = {
154	  id: string; userId: string; status: string; prompt: string; changeRequest: string | null; baseBuildId: string | null; rootBuildId: string | null;
155	  mcVersion: string; pluginName: string | null; version: string | null; result: unknown; error: string | null; errorCode: string | null; attempts: number;
156	  durationMs: number | null; jarName: string | null; jarSize: number | null; jarSha256: string | null; cyrus: unknown; createdAt: Date; updatedAt: Date; finishedAt: Date | null;
157	};
158	
159	export type V1Deps = {
160	  config: () => ApiV1Config;
161	  now: () => Date;
162	  replay: ReplayCache;
163	  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec: number; remaining: number };
164	  store: {
165	    /** newest first; `after` = the last row of the previous page */
166	    listProjects(userId: string, limit: number, after: { createdAt: Date; id: string } | null): Promise<ProjectRow[]>;
167	    getProject(id: string): Promise<ProjectRow | null>;
168	    revisions(ids: string[]): Promise<RevisionRow[]>;
169	    getBuild(id: string): Promise<BuildRow | null>;
170	  };
171	  /** null = no catalog backend configured (503 catalog_unavailable) */
172	  catalog: () => Promise<CatalogIndex | null>;
173	  /** the subject's raw plan (asset-gate understands it); a throw = unknown = fail closed */
174	  planOf: (userId: string) => Promise<unknown>;
175	  proprietaryCleared: () => boolean;
176	  requestId?: () => string;
177	  log?: (msg: string) => void;
178	  /** phase 2 write operations; absent = every write answers 503 writes_unavailable */
179	  writes?: V1WriteDeps;
180	};
181	
182	function intParam(u: URL, name: string, min: number, max: number, dflt: number): number {
183	  const raw = u.searchParams.get(name);
184	  if (raw === null || raw === "") return dflt;
185	  if (!/^\d{1,6}$/.test(raw) || Number(raw) < min || Number(raw) > max) throw new BadInput([issue(name, `${name} must be a whole number ${min}-${max}`)]);
186	  return Number(raw);
187	}
188	const encCursor = (o: Record<string, unknown>) => Buffer.from(JSON.stringify(o)).toString("base64url");
189	function decCursor<T>(raw: string | null, check: (o: Record<string, unknown>) => T | null): T | null {
190	  if (!raw) return null;
191	  try {
192	    if (raw.length > 200) throw new Error();
193	    const o = JSON.parse(Buffer.from(raw, "base64url").toString("utf8"));
194	    const v = o && typeof o === "object" ? check(o) : null;
195	    if (v) return v;
196	  } catch { /* falls through */ }
197	  throw new BadInput([issue("cursor", "cursor is not one this API returned")]);
198	}
199	
200	// ------------------------------------------------------------------------------------------------ auth
201	type Caller = { key: ApiKey; subject: string | null };
202	type AuthOut = { ok: true; caller: Caller } | { ok: false; res: Response };
203	
204	function authenticate(req: Request, op: Operation, cfg: ApiV1Config, deps: V1Deps, ctx: Ctx): AuthOut {
205	  const no = (res: Response): AuthOut => ({ ok: false, res });
206	  const h = req.headers.get("authorization") ?? "";
207	  const tok = parseServiceToken(h.startsWith("Bearer ") ? h.slice(7) : "");
208	  // unknown key and wrong secret look the same to the caller
209	  const key = tok ? cfg.keys.find((k) => k.id === tok.keyId) ?? null : null;
210	  if (!tok || !key || !safeEqual(sha256Hex(tok.secret), key.sha256)) return no(fail(ctx, 401, "unauthorized", "a valid Cyrus service token is required", undefined, { "www-authenticate": 'Bearer realm="cyrus-api-v1"' }));
211	  const missing = op.scopes.filter((s) => !key.scopes.includes(s));
212	  if (missing.length) return no(fail(ctx, 403, "forbidden_scope", `this token lacks ${missing.join(", ")}`));
213	  const rl = deps.rateLimit(`cyrus-api-v1:${key.id}`, key.rpm, 60_000);
214	  ctx.headers["ratelimit-limit"] = String(key.rpm);
215	  ctx.headers["ratelimit-remaining"] = String(Math.max(0, rl.remaining));
216	  if (!rl.ok) return no(fail(ctx, 429, "rate_limited", "too many requests for this token", undefined, { "retry-after": String(Math.max(1, rl.retryAfterSec)) }));
217	  if (!op.subject) return { ok: true, caller: { key, subject: null } };
218	  // the subject id is a platform account id: only a client the owner named as an identity source may assert one
219	  if (!(cfg.identityClients ?? []).includes(key.client)) return no(fail(ctx, 403, "subject_not_allowed", "this client may not act for an account"));
220	  const raw = req.headers.get("cyrus-subject");
221	  if (!raw) return no(fail(ctx, 400, "subject_required", "this operation acts for one account: send the Cyrus-Subject assertion"));
222	  const v = verifySubjectAssertion(raw, { client: key.client, keys: cfg.subjectKeys, nowMs: deps.now().getTime(), replay: deps.replay });
223	  if (!v.ok) return no(fail(ctx, 401, v.code, v.message));
224	  return { ok: true, caller: { key, subject: v.claims.sub } };
225	}
226	
227	// ------------------------------------------------------------------------------------------------ views
228	const files = (m: unknown) => (Array.isArray(m) ? m.length : 0);
229	export const revisionView = (r: RevisionRow) => ({ id: r.id, seq: r.seq, kind: r.kind, status: r.status, message: r.message, modBuildId: r.modBuildId, files: files(r.manifest), createdAt: iso(r.createdAt) });
230	export const projectView = (p: ProjectRow) => ({
231	  id: p.id, game: p.game, namespace: p.namespace, title: p.title, rootBuildId: p.rootBuildId, headRevisionId: p.headRevisionId,
232	  lastPassingRevisionId: p.lastPassingRevisionId, revisionCount: p.revisionCount, createdAt: iso(p.createdAt), updatedAt: iso(p.updatedAt),
233	});
234	const TERMINAL = new Set(["succeeded", "failed"]);
235	export function buildView(b: BuildRow) {
236	  const meta = (b.cyrus && typeof b.cyrus === "object" ? b.cyrus : {}) as Record<string, unknown>;
237	  const result = (b.result && typeof b.result === "object" ? b.result : {}) as Record<string, unknown>;
238	  return {
239	    id: b.id, status: b.status, terminal: TERMINAL.has(b.status),
240	    target: { game: typeof meta.game === "string" ? meta.game : "minecraft", version: b.mcVersion },
241	    pluginName: b.pluginName, version: b.version, prompt: b.prompt, changeRequest: b.changeRequest, baseBuildId: b.baseBuildId, rootBuildId: b.rootBuildId,
242	    summary: typeof result.summary === "string" ? result.summary : null,
243	    error: b.status === "failed" ? { code: b.errorCode, message: b.error ?? "the build failed" } : null,
244	    artifact: b.jarSha256 ? { name: b.jarName, size: b.jarSize, sha256: b.jarSha256 } : null,
245	    attempts: b.attempts, durationMs: b.durationMs, createdAt: iso(b.createdAt), updatedAt: iso(b.updatedAt), finishedAt: iso(b.finishedAt),
246	  };
247	}
248	export const catalogEntryView = (e: CatalogEntry) => ({
249	  id: e.id, ref: catalogRef(e.id), kind: e.kind, title: e.title, shortDescription: e.shortDescription, tags: e.tags, categories: e.categories, useFor: e.useFor,
250	  style: e.style, quality: e.quality, games: e.games, tech: e.tech, legalClass: e.legalClass, thumbnail: e.thumbnail,
251	  licence: { tier: e.licence.tier, spdx: e.licence.spdx, attribution: e.licence.attribution },
252	  ...(e.licence.tier === "proprietary-nxeon" ? { rule: "proprietary library: ship transformed (pitch/edit), never the original file" } : {}),
253	});
254	
255	// ------------------------------------------------------------------------------------------------ operations
256	const re = (p: string) => new RegExp(p);
257	const PROJECT_RE = re(PROJECT_ID_PATTERN), BUILD_RE = re(BUILD_ID_PATTERN), ENTRY_RE = re(ENTRY_ID_PATTERN);
258	type Handler = (a: { req: Request; url: URL; params: Record<string, string>; caller: Caller; deps: V1Deps; ctx: Ctx }) => Promise<Response>;
259	
260	const notFound = (ctx: Ctx) => fail(ctx, 404, "not_found", "not found");
261	
262	async function gateFor(subject: string, deps: V1Deps) {
263	  let plan: unknown = null;
264	  try { plan = await deps.planOf(subject); } catch { plan = null; } // unknown plan = fail closed
265	  return catalogAccess(plan, deps.proprietaryCleared());
266	}
267	
268	const HANDLERS: Record<LiveOperationId, Handler> = {
269	  async getHealth({ caller, deps, ctx }) {
270	    return send(ctx, 200, { ok: true, api: "cyrus", version: API_VERSION, time: deps.now().toISOString(), client: caller.key.client, scopes: caller.key.scopes });
271	  },
272	
273	  async listProjects({ url, caller, deps, ctx }) {
274	    const limit = intParam(url, "limit", 1, 100, 20);
275	    const after = decCursor(url.searchParams.get("cursor"), (o) => (typeof o.t === "string" && typeof o.id === "string" && !Number.isNaN(Date.parse(o.t)) ? { createdAt: new Date(o.t), id: o.id } : null));
276	    const rows = await deps.store.listProjects(caller.subject!, limit + 1, after);
277	    const page = rows.slice(0, limit);
278	    const last = page[page.length - 1];
279	    return send(ctx, 200, { data: page.map(projectView), nextCursor: rows.length > limit && last ? encCursor({ t: last.createdAt.toISOString(), id: last.id }) : null });
280	  },
281	
282	  async getProject({ params, caller, deps, ctx }) {
283	    const id = params.projectId ?? "";
284	    if (!PROJECT_RE.test(id)) return notFound(ctx);
285	    const p = await deps.store.getProject(id);
286	    if (!p || p.userId !== caller.subject) return notFound(ctx);
287	    const ids = [p.headRevisionId, p.lastPassingRevisionId].filter((x): x is string => !!x);
288	    const revs = ids.length ? await deps.store.revisions([...new Set(ids)]) : [];
289	    const own = (rid: string | null) => revs.find((r) => r.id === rid && r.projectId === p.id) ?? null;
290	    const head = own(p.headRevisionId), lastPassing = own(p.lastPassingRevisionId);
291	    return send(ctx, 200, { ...projectView(p), head: head ? revisionView(head) : null, lastPassing: lastPassing ? revisionView(lastPassing) : null, spec: head?.spec ?? null });
292	  },
293	
294	  async getBuild({ params, caller, deps, ctx }) {
295	    const id = params.buildId ?? "";
296	    if (!BUILD_RE.test(id)) return notFound(ctx);
297	    const b = await deps.store.getBuild(id);
298	    if (!b || b.userId !== caller.subject) return notFound(ctx);
299	    return send(ctx, 200, buildView(b));
300	  },
301	
302	  async searchCatalog({ url, caller, deps, ctx }) {
303	    const q = (url.searchParams.get("q") ?? "").trim();
304	    const issues: ApiIssue[] = [];
305	    if (q.length < 2 || q.length > 120) issues.push(issue("q", "q must be 2-120 characters"));
306	    const kindRaw = url.searchParams.get("kind");
307	    if (kindRaw !== null && !(CATALOG_KINDS as readonly string[]).includes(kindRaw)) issues.push(issue("kind", `kind must be one of ${CATALOG_KINDS.join(", ")}`));
308	    const gameRaw = url.searchParams.get("game");
309	    if (gameRaw !== null && !/^[a-z][a-z0-9-]{1,31}$/.test(gameRaw)) issues.push(issue("game", "game must be a game id"));
310	    if (issues.length) throw new BadInput(issues);
311	    const minQuality = intParam(url, "minQuality", 0, 100, 40);
312	    const limit = intParam(url, "limit", 1, 20, 10);
313	    const offset = decCursor(url.searchParams.get("cursor"), (o) => (Number.isInteger(o.o) && (o.o as number) >= 0 && (o.o as number) <= 10_000 ? (o.o as number) : null)) ?? 0;
314	    const index = await deps.catalog();
315	    if (!index) return fail(ctx, 503, "catalog_unavailable", "the asset catalog is not available on this deployment");
316	    const a = await gateFor(caller.subject!, deps);
317	    if (!a.plan) return fail(ctx, 403, "plan_unknown", "the account's plan could not be read; assets cannot be picked right now");
318	    let kinds: CatalogKind[] = a.kinds;
319	    if (kindRaw !== null) kinds = kinds.includes(kindRaw as CatalogKind) ? [kindRaw as CatalogKind] : [];
320	    if (!kinds.length || !a.tiers.length) return fail(ctx, 403, "asset_locked", "this plan cannot use library assets of that kind");
