import { readFileSync, statSync } from "node:fs";
import { cyrusDb } from "../../db";
import { getHost } from "../../host";
import { tierOf } from "../../tokens/access";
import { validateCatalogEntry } from "../../library/v2/entry";
import { createMemoryCatalogIndex, type CatalogIndex } from "../../library/v2/retrieval";
import { apiV1Config } from "./config";
import { ReplayCache } from "./signing";
import type { V1Deps } from "./http";
import { v1WriteDeps } from "./deps-writes";
import type { DeliveryApiDeps } from "../../delivery/api";

const replay = new ReplayCache();

/** Max bytes of CYRUS_API_V1_CATALOG_FILE read into memory (a stopgap until the catalog has a database index). */
export const CATALOG_FILE_MAX_BYTES = 64 * 1024 * 1024;
let catalogCache: { key: string; index: CatalogIndex } | null = null;

/** A memory index over a CatalogEntry JSONL file; invalid lines are skipped, a too-large or missing file = no catalog. */
export async function fileCatalog(file: string | null): Promise<CatalogIndex | null> {
  if (!file) return null;
  let st;
  try { st = statSync(file); } catch { return null; }
  if (!st.isFile() || st.size > CATALOG_FILE_MAX_BYTES) return null;
  const key = `${file}:${st.size}:${st.mtimeMs}`;
  if (catalogCache?.key === key) return catalogCache.index;
  const entries = [];
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue;
    try { const v = validateCatalogEntry(JSON.parse(line)); if (v.ok) entries.push(v.entry); } catch { /* skip */ }
  }
  const index = createMemoryCatalogIndex(entries);
  catalogCache = { key, index };
  return index;
}

