    revisions: (ids) => cyrusDb.cyrusRevision.findMany({ where: { id: { in: ids } }, select: { id: true, projectId: true, seq: true, kind: true, status: true, message: true, modBuildId: true, manifest: true, spec: true, createdAt: true } }),
