// r44: personal API keys accepted by Cyrus API v1 (lib/cyrus/api/v1/http.ts authenticatePersonal): flag off = refused,
// owner = subject, scopes, revoked/expired, suspended account, per-key + per-account rate limits, audit hook, last-used
// throttle, service tokens unaffected, OpenAPI documents the scheme.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { handleV1, type ProjectRow, type V1Deps } from "../lib/cyrus/api/v1/http";
import { apiV1Config } from "../lib/cyrus/api/v1/config";
import { ReplayCache, mintServiceToken } from "../lib/cyrus/api/v1/signing";
import { buildOpenApi } from "../lib/cyrus/api/v1/openapi";
import { createKey, memoryKeyStore, verifyKey } from "../lib/cyrus/app/apikeys";
import { shouldAuditPersonalRead } from "../lib/cyrus/api/v1/deps";

const NOW = new Date("2026-10-11T12:00:00Z");
const svc = mintServiceToken("nxeon01");
const ENV_ON = { CYRUS_API_V1: "1", CYRUS_API_V1_PERSONAL_KEYS: "1", CYRUS_API_V1_PERSONAL_RPM: "3", CYRUS_API_V1_KEYS: JSON.stringify([{ id: "nxeon01", client: "nxeon", sha256: svc.sha256, scopes: ["projects:read"] }]) };
const ENV_OFF = { ...ENV_ON, CYRUS_API_V1_PERSONAL_KEYS: undefined };
const proj = (id: string, userId: string): ProjectRow => ({ id, userId, game: "minecraft", namespace: "nx_a", title: "T", rootBuildId: null, headRevisionId: null, lastPassingRevisionId: null, revisionCount: 0, createdAt: NOW, updatedAt: NOW });
const PROJECTS = [proj("cp00000000000000000001", "user_a"), proj("cp00000000000000000002", "user_b")];

function setup(env: Record<string, string | undefined> = ENV_ON, o: { banned?: string[] } = {}) {
  const store = memoryKeyStore();
  const audits: Record<string, unknown>[] = [];
  const windows = new Map<string, number>();
  const d: V1Deps = {
    config: () => apiV1Config(env), now: () => NOW, replay: new ReplayCache(),
    rateLimit: (key, max) => { const n = (windows.get(key) ?? 0) + 1; windows.set(key, n); return { ok: n <= max, retryAfterSec: 7, remaining: Math.max(0, max - n) }; },
    store: {
      async listProjects(u) { return PROJECTS.filter((p) => p.userId === u); },
      async getProject(id) { return PROJECTS.find((p) => p.id === id) ?? null; },
      async revisions() { return []; }, async getBuild() { return null; },
    },
    catalog: async () => null, planOf: async () => "saka", proprietaryCleared: () => false, requestId: () => "req_t",
    personal: { verify: (t) => verifyKey(store, t, NOW), allowed: async (u) => !(o.banned ?? []).includes(u), audit: async (e) => { audits.push(e); } },
  };
  return { store, d, audits };
}
async function call(d: V1Deps, op: "getHealth" | "listProjects" | "getProject", path: string, token: string, params: Record<string, string> = {}) {
  const res = await handleV1(op, new Request(`https://c.test/api/cyrus/v1${path}`, { headers: { authorization: `Bearer ${token}` } }), params, d);
  return { status: res.status, body: await res.json() as any, headers: res.headers };
}

describe("Cyrus API v1: personal keys (r44)", () => {
  it("flag off: a valid personal key is a 401, exactly like an unknown token", async () => {
    const { store, d } = setup(ENV_OFF);
    const k = await createKey(store, "user_a", { name: "ci", scopes: ["projects:read"] }, NOW);
    assert.ok(k.ok);
    const r = await call(d, "listProjects", "/projects", (k as any).key);
    assert.equal(r.status, 401); assert.equal(r.body.error.code, "unauthorized");
  });
  it("on: the key acts as its owner with no Cyrus-Subject; other users' objects stay 404", async () => {
    const { store, d } = setup();
    const k = await createKey(store, "user_a", { name: "ci", scopes: ["projects:read"] }, NOW) as any;
    const r = await call(d, "listProjects", "/projects", k.key);
    assert.equal(r.status, 200); assert.deepEqual(r.body.data.map((p: any) => p.id), [PROJECTS[0].id]);
    const other = await call(d, "getProject", `/projects/${PROJECTS[1].id}`, k.key, { projectId: PROJECTS[1].id });
    assert.equal(other.status, 404);
    const h = await call(d, "getHealth", "/health", k.key);
    assert.equal(h.body.client, "personal"); assert.deepEqual(h.body.scopes, ["projects:read"]);
  });
  it("scopes: a key without projects:read gets 403 forbidden_scope", async () => {
    const { store, d } = setup();
    const k = await createKey(store, "user_a", { name: "cat", scopes: ["catalog:read"] }, NOW) as any;
    const r = await call(d, "listProjects", "/projects", k.key);
    assert.equal(r.status, 403); assert.equal(r.body.error.code, "forbidden_scope");
  });
  it("revoked, expired, tampered keys are 401", async () => {
    const { store, d } = setup();
    const k = await createKey(store, "user_a", { name: "x", scopes: ["projects:read"] }, NOW) as any;
    await store.revoke("user_a", k.view.id, NOW);
    assert.equal((await call(d, "listProjects", "/projects", k.key)).status, 401);
    const e = await createKey(store, "user_a", { name: "y", scopes: ["projects:read"], expiryDays: 30 }, new Date(NOW.getTime() - 40 * 86_400_000)) as any;
    assert.equal((await call(d, "listProjects", "/projects", e.key)).status, 401);
    const t = await createKey(store, "user_a", { name: "z", scopes: ["projects:read"] }, NOW) as any;
    assert.equal((await call(d, "listProjects", "/projects", t.key.slice(0, -1) + (t.key.endsWith("A") ? "B" : "A"))).status, 401);
  });
  it("a suspended / not-allowed account is 403 not_allowed", async () => {
    const { store, d } = setup(ENV_ON, { banned: ["user_a"] });
    const k = await createKey(store, "user_a", { name: "x", scopes: ["projects:read"] }, NOW) as any;
    const r = await call(d, "listProjects", "/projects", k.key);
    assert.equal(r.status, 403); assert.equal(r.body.error.code, "not_allowed");
  });
  it("rate limit per key (rpm) and per account (2x across keys)", async () => {
    const { store, d } = setup();
    const a = await createKey(store, "user_a", { name: "a", scopes: ["projects:read"] }, NOW) as any;
    const b = await createKey(store, "user_a", { name: "b", scopes: ["projects:read"] }, NOW) as any;
    const c = await createKey(store, "user_a", { name: "c", scopes: ["projects:read"] }, NOW) as any;
    for (let i = 0; i < 3; i++) assert.equal((await call(d, "listProjects", "/projects", a.key)).status, 200);
    const r = await call(d, "listProjects", "/projects", a.key);
    assert.equal(r.status, 429); assert.equal(r.headers.get("retry-after"), "7");
    for (let i = 0; i < 2; i++) assert.equal((await call(d, "listProjects", "/projects", b.key)).status, 200);
    // account total = 6 (a's 4th call counted too): c is refused even though c itself is fresh
    assert.equal((await call(d, "listProjects", "/projects", c.key)).status, 429);
  });
  it("audit hook: one row per call with key id + status; last-used written at most once a minute", async () => {
    const { store, d, audits } = setup();
    const k = await createKey(store, "user_a", { name: "a", scopes: ["projects:read"] }, NOW) as any;
    await call(d, "listProjects", "/projects", k.key);
    await call(d, "listProjects", "/projects", k.key);
    assert.equal(audits.length, 2); assert.equal((audits[0] as any).keyId, k.view.id); assert.equal((audits[0] as any).status, 200);
    assert.equal(store.rows[0].lastUsedAt?.toISOString(), NOW.toISOString());
    let touches = 0; const orig = store.touch; store.touch = async (id, at) => { touches++; return orig(id, at); };
    await verifyKey(store, k.key, new Date(NOW.getTime() + 30_000));
    assert.equal(touches, 0);
    await verifyKey(store, k.key, new Date(NOW.getTime() + 61_000));
    assert.equal(touches, 1);
  });
  it("read audit throttle: once per key+op per 10 minutes", () => {
    const seen = new Map<string, number>();
    assert.equal(shouldAuditPersonalRead("k1", "listProjects", 0, seen), true);
    assert.equal(shouldAuditPersonalRead("k1", "listProjects", 599_000, seen), false);
    assert.equal(shouldAuditPersonalRead("k1", "getProject", 1, seen), true);
    assert.equal(shouldAuditPersonalRead("k1", "listProjects", 600_001, seen), true);
  });
  it("service tokens still work unchanged when personal keys are on", async () => {
    const { d } = setup();
    const r = await call(d, "getHealth", "/health", svc.token);
    assert.equal(r.status, 200); assert.equal(r.body.client, "nxeon");
  });
  it("bad CYRUS_API_V1_PERSONAL_RPM fails closed (503) and turns personal keys off", async () => {
    const cfg = apiV1Config({ ...ENV_ON, CYRUS_API_V1_PERSONAL_RPM: "0" });
    assert.ok(cfg.error); assert.equal(cfg.personalKeys, false);
  });
  it("OpenAPI: personalKey scheme exists and is offered on customer operations, never on admin:read ones", () => {
    const doc = buildOpenApi() as any;
    assert.ok(doc.components.securitySchemes.personalKey);
    assert.ok(doc.paths["/projects"].get.security.some((s: any) => "personalKey" in s));
    for (const p of Object.values(doc.paths) as any[]) for (const op of Object.values(p) as any[]) {
      if (op?.["x-cyrus-scopes"]?.includes?.("admin:read")) assert.ok(!op.security.some((s: any) => "personalKey" in s));
    }
  });
});

