  { id: "server.restart", label: "Restart the server", detail: "Within a daily budget, when an install needs it." },
  { id: "logs.read.tail", label: "Read recent logs", detail: "The tail of the console, for Server Doctor and post-install checks." },
  { id: "pack.set", label: "Set the resource pack", detail: "The resource-pack URL and hash in server.properties." },
] as const;
export type GrantScope = (typeof GRANT_SCOPES)[number]["id"];

export type ServerGrant = { serverId: string; scopes: GrantScope[]; grantedAt: string; lastUsedAt: string | null };
