"use server";
// Account server actions (r39). Every action re-runs the app gate (fail closed) and acts only on the viewer's own
// rows; ids from the client are only ever used together with the viewer's user id.
import { checkRateLimit } from "@/lib/rate-limit";
import { db } from "@/lib/db";
import { createKey, toView, type ApiKeyView } from "@/lib/cyrus/app/apikeys";
import { prismaDataStore, prismaKeyStore } from "@/lib/cyrus/app/store";
import { prefsFromForm } from "@/lib/cyrus/notify/events";
import { savePrefs } from "@/lib/cyrus/notify";
import { requestData } from "@/lib/cyrus/app/data-requests";
import { appGrants } from "../_grants";
import { appViewerOrNull } from "../_gate";

type R<T = object> = ({ ok: true } & T) | { ok: false; error: string };
const NOPE = { ok: false as const, error: "Not found." };
const limited = (key: string, max: number) => { const r = checkRateLimit(key, { max, windowMs: 60_000 }); return r.ok ? null : { ok: false as const, error: `Too many requests. Try again in ${r.retryAfterSec}s.` }; };
const audit = (userId: string, action: string, detail: string) => db.auditLog.create({ data: { userId, action, detail } }).catch(() => {});

export async function createApiKeyAction(input: { name: string; scopes: string[]; expiryDays: number }): Promise<R<{ key: string; view: ApiKeyView }>> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:key:${v.user.id}`, 6); if (rl) return rl;
  const r = await createKey(prismaKeyStore, v.user.id, input);
  if (!r.ok) return r;
  await audit(v.user.id, "cyrus.apikey.create", `${r.view.id} ${r.view.prefix} [${r.view.scopes.join(",")}]`);
  return { ok: true, key: r.key, view: r.view };
}

export async function revokeApiKeyAction(id: string): Promise<R<{ keys: ApiKeyView[] }>> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:keyrev:${v.user.id}`, 20); if (rl) return rl;
  const ok = await prismaKeyStore.revoke(v.user.id, String(id).slice(0, 64), new Date());
  if (!ok) return { ok: false, error: "That key is already revoked or does not exist." };
  await audit(v.user.id, "cyrus.apikey.revoke", String(id).slice(0, 64));
  const now = new Date();
  return { ok: true, keys: (await prismaKeyStore.listForUser(v.user.id)).map((k) => toView(k, now)) };
}

export async function savePrefsAction(fields: [string, string][]): Promise<R> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:prefs:${v.user.id}`, 20); if (rl) return rl;
  const m = new Map(fields.slice(0, 100));
  const ok = await savePrefs(v.user.id, prefsFromForm((k) => m.get(k) ?? null));
  return ok ? { ok: true } : { ok: false, error: "Could not save." };
}

export async function requestDataAction(input: { kind: string; confirm?: string; note?: string }): Promise<R> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const rl = limited(`cyrus:app:data:${v.user.id}`, 5); if (rl) return rl;
  const r = await requestData(prismaDataStore, v.user.id, input);
  if (!r.ok) return r;
  await audit(v.user.id, `cyrus.data.${r.row.kind}.request`, r.row.id);
  return { ok: true };
}

export async function cancelDataRequestAction(id: string): Promise<R> {
  const v = await appViewerOrNull(); if (!v) return NOPE;
  const ok = await prismaDataStore.cancel(v.user.id, String(id).slice(0, 64));
  return ok ? { ok: true } : { ok: false, error: "Only a request that has not started can be cancelled." };
}

