// Cyrus data export + deletion JOBS (r44). r39 only recorded requests; this runs them. Pure core + deps (tests pass
// fakes; ./data-jobs.server.ts wires Prisma, disk, gdpr and the host). Inert unless CYRUS_DATA_JOBS=1 on the worker.
//
// Status states (honest: the customer sees exactly these):
//   export   requested -> in_progress -> ready (download for EXPORT_TTL_DAYS) -> expired        | failed (retried 3x)
//   delete   requested (grace: cancellable until graceUntil) -> in_progress -> done             | failed (retried 3x)
//            requested + note "waiting" when the grace is over but CYRUS_GDPR_ERASE is off: nothing is deleted.
// Cascade rules for a deletion (policy per table: lib/cyrus/admin/ops.ts CYRUS_GDPR_TABLES):
//   - projects, revisions, project assets, drafts, pages, posts, stars, keys, notification prefs: deleted
//   - builds: anonymised (prompt cleared; the token-charge rows behind them stay: financial)
//   - token ledger / lots / plan: retained (financial), keyed to the user id the platform keeps anyway
//   - library contributions: PUBLISHED entries stay in the library under their licence with the contributor id cleared
//     (the takedown/ownership rule: the owner can still take one down; projects and mods that use it keep working from
//     their own copy, lib/cyrus/library/backend/moderation.ts). Contributions not yet published are removed.
//   - server grants: revoked on the platform side
//   - export archives of the person: removed from disk
export const EXPORT_TTL_DAYS = 7;
export const DELETE_GRACE_DAYS = 14;
export const MAX_ATTEMPTS = 3;
const DAY = 86_400_000;

export type JobRow = {
  id: string; userId: string; kind: string; status: string; note: string | null; createdAt: Date; completedAt: Date | null;
  graceUntil?: Date | null; expiresAt?: Date | null; archivePath?: string | null; archiveBytes?: number | null; archiveSha256?: string | null;
  attempts?: number; error?: string | null; result?: unknown;
};
export type JobPatch = Partial<Pick<JobRow, "status" | "note" | "completedAt" | "expiresAt" | "archivePath" | "archiveBytes" | "archiveSha256" | "attempts" | "error" | "result">> & { startedAt?: Date };

export type DataJobDeps = {
  now(): Date;
  /** oldest first: exports in `requested`; deletions in `requested` whose grace is over; ready exports past expiresAt */
  due(now: Date): Promise<{ exports: JobRow[]; deletes: JobRow[]; expired: JobRow[] }>;
  /** atomic from-status -> patch; false = someone else took it (two workers never run one job) */
  claim(id: string, from: string, patch: JobPatch): Promise<boolean>;
  update(id: string, patch: JobPatch): Promise<void>;
  collect(userId: string): Promise<{ files: { path: string; content: string }[]; counts: Record<string, number> }>;
  writeArchive(row: JobRow, files: { path: string; content: string }[]): Promise<{ path: string; bytes: number; sha256: string }>;
  removeFile(path: string): Promise<void>;
  /** paths of every archive this person has on disk (deleted with their data) */
  archivesOf(userId: string): Promise<string[]>;
  eraseEnabled(): boolean;
  erase(userId: string): Promise<{ deleted: Record<string, number>; anonymised: Record<string, number>; retained: Record<string, number>; anonId: string; salt: string }>;
  /** the parts gdprErase does not own: keys, notification prefs + inbox, grants, unpublished contributions */
  eraseExtras(userId: string): Promise<Record<string, number>>;
  audit(e: { userId: string; action: string; target: string; detail: Record<string, unknown> }): Promise<void>;
  log?(m: string): void;
};

export type TickResult = { exported: number; deleted: number; expired: number; waiting: number; failed: number };

const errText = (e: unknown) => String((e as Error)?.message ?? e).replace(/postgres(ql)?:\/\/\S+/g, "<db>").slice(0, 300);

export async function runExport(row: JobRow, d: DataJobDeps): Promise<"ready" | "failed" | "skipped"> {
  const now = d.now();
  const attempts = (row.attempts ?? 0) + 1;
  if (!(await d.claim(row.id, "requested", { status: "in_progress", startedAt: now, attempts, error: null }))) return "skipped";
  try {
    const { files, counts } = await d.collect(row.userId);
    const a = await d.writeArchive(row, files);
    await d.update(row.id, { status: "ready", archivePath: a.path, archiveBytes: a.bytes, archiveSha256: a.sha256, completedAt: d.now(), expiresAt: new Date(d.now().getTime() + EXPORT_TTL_DAYS * DAY), result: { counts } });
    await d.audit({ userId: row.userId, action: "cyrus.data.export.ready", target: row.id, detail: { bytes: a.bytes, sha256: a.sha256, counts } });
    return "ready";
  } catch (e) {
    const final = attempts >= MAX_ATTEMPTS;
    await d.update(row.id, { status: final ? "failed" : "requested", error: errText(e) }).catch(() => {});
    await d.audit({ userId: row.userId, action: "cyrus.data.export.error", target: row.id, detail: { attempts, final, error: errText(e) } }).catch(() => {});
    return "failed";
  }
}

export async function runDelete(row: JobRow, d: DataJobDeps): Promise<"done" | "waiting" | "failed" | "skipped"> {
  const now = d.now();
  if (row.graceUntil && row.graceUntil > now) return "skipped";
  if (!d.eraseEnabled()) {
    if (row.note !== "waiting") await d.update(row.id, { note: "waiting" }).catch(() => {});
    return "waiting";
  }
  const attempts = (row.attempts ?? 0) + 1;
  if (!(await d.claim(row.id, "requested", { status: "in_progress", startedAt: now, attempts, error: null }))) return "skipped";
  try {
    const extras = await d.eraseExtras(row.userId);
    const r = await d.erase(row.userId);
    let archives = 0;
    for (const p of await d.archivesOf(row.userId)) { await d.removeFile(p).catch(() => {}); archives++; }
    const result = { deleted: r.deleted, anonymised: r.anonymised, retained: r.retained, extras, archives, anonId: r.anonId };
    await d.update(row.id, { status: "done", note: null, completedAt: d.now(), result });
    // the salt lives only in the audit row (re-identifying anonymised rows needs it; staff only)
    await d.audit({ userId: row.userId, action: "cyrus.data.delete.done", target: row.id, detail: { ...result, salt: r.salt } });
    return "done";
  } catch (e) {
    const final = attempts >= MAX_ATTEMPTS;
    await d.update(row.id, { status: final ? "failed" : "requested", error: errText(e) }).catch(() => {});
    await d.audit({ userId: row.userId, action: "cyrus.data.delete.error", target: row.id, detail: { attempts, final, error: errText(e) } }).catch(() => {});
    return "failed";
  }
}

/** One worker tick: expire old archives, then at most `max` exports and `max` deletions, oldest first. Never throws. */
export async function dataJobsTick(d: DataJobDeps, max = 3): Promise<TickResult> {
  const out: TickResult = { exported: 0, deleted: 0, expired: 0, waiting: 0, failed: 0 };
  let due: Awaited<ReturnType<DataJobDeps["due"]>>;
  try { due = await d.due(d.now()); } catch (e) { d.log?.(`[cyrus-data-jobs] due: ${errText(e)}`); return out; }
  for (const r of due.expired) {
    if (!(await d.claim(r.id, "ready", { status: "expired", archivePath: null }).catch(() => false))) continue;
    if (r.archivePath) await d.removeFile(r.archivePath).catch(() => {});
    out.expired++;
  }
  for (const r of due.exports.slice(0, max)) { const s = await runExport(r, d); if (s === "ready") out.exported++; else if (s === "failed") out.failed++; }
  for (const r of due.deletes.slice(0, max)) { const s = await runDelete(r, d); if (s === "done") out.deleted++; else if (s === "waiting") out.waiting++; else if (s === "failed") out.failed++; }
  return out;
}

/** Owner-only download check: the archive exists only while `ready` and unexpired, and only for its own user. */
export function downloadable(row: JobRow | null, userId: string, now: Date): row is JobRow & { archivePath: string } {
  return !!row && row.userId === userId && row.kind === "export" && row.status === "ready" && !!row.archivePath && !!row.expiresAt && row.expiresAt > now;
}

/** What the customer sees for a request (one line, no internals). */
export function statusLine(r: JobRow, now: Date): { pill: string; tone: "ok" | "wait" | "none" | "bad"; detail: string } {
  const d = (x: Date | null | undefined) => (x ? x.toISOString().slice(0, 10) : "");
  if (r.kind === "export") {
    if (r.status === "ready") return { pill: "ready", tone: "ok", detail: `download until ${d(r.expiresAt)}` };
    if (r.status === "expired") return { pill: "expired", tone: "none", detail: "the archive was removed; request a new one" };
    if (r.status === "in_progress") return { pill: "preparing", tone: "wait", detail: "building your archive" };
    if (r.status === "failed") return { pill: "failed", tone: "bad", detail: "we could not build it; support has been told" };
  } else {
    if (r.status === "requested" && r.graceUntil && r.graceUntil > now) return { pill: "scheduled", tone: "wait", detail: `deletes on ${d(r.graceUntil)}; you can cancel until then` };
    if (r.status === "requested" && r.note === "waiting") return { pill: "waiting", tone: "wait", detail: "queued for staff to run; nothing deleted yet" };
    if (r.status === "in_progress") return { pill: "deleting", tone: "wait", detail: "in progress" };
    if (r.status === "done") return { pill: "deleted", tone: "ok", detail: `finished ${d(r.completedAt)}` };
    if (r.status === "failed") return { pill: "failed", tone: "bad", detail: "stopped part way; support has been told" };
  }
  if (r.status === "cancelled") return { pill: "cancelled", tone: "none", detail: "" };
  return { pill: "queued", tone: "wait", detail: "" };
}

export const graceUntilFor = (kind: string, now: Date) => (kind === "delete" ? new Date(now.getTime() + DELETE_GRACE_DAYS * DAY) : null);

