// fakes; ./data-jobs.server.ts wires Prisma, disk, gdpr and the host). Inert unless CYRUS_DATA_JOBS=1 on the worker.
//
// Status states (honest: the customer sees exactly these):
//   export   requested -> in_progress -> ready (download for EXPORT_TTL_DAYS) -> expired        | failed (retried 3x)
//   delete   requested (grace: cancellable until graceUntil) -> in_progress -> done             | failed (retried 3x)
//            requested + note "waiting" when the grace is over but CYRUS_GDPR_ERASE is off: nothing is deleted.
// Cascade rules for a deletion (policy per table: lib/cyrus/admin/ops.ts CYRUS_GDPR_TABLES):
//   - projects, revisions, project assets, drafts, pages, posts, stars, keys, notification prefs: deleted
//   - builds: anonymised (prompt cleared; the token-charge rows behind them stay: financial)
//   - token ledger / lots / plan: retained (financial), keyed to the user id the platform keeps anyway
//   - library contributions: PUBLISHED entries stay in the library under their licence with the contributor id cleared
//     (the takedown/ownership rule: the owner can still take one down; projects and mods that use it keep working from
//     their own copy, lib/cyrus/library/backend/moderation.ts). Contributions not yet published are removed.
//   - server grants: revoked on the platform side
//   - export archives of the person: removed from disk
export const EXPORT_TTL_DAYS = 7;
export const DELETE_GRACE_DAYS = 14;
export const MAX_ATTEMPTS = 3;
const DAY = 86_400_000;

export type JobRow = {
  id: string; userId: string; kind: string; status: string; note: string | null; createdAt: Date; completedAt: Date | null;
  graceUntil?: Date | null; expiresAt?: Date | null; archivePath?: string | null; archiveBytes?: number | null; archiveSha256?: string | null;
  attempts?: number; error?: string | null; result?: unknown;
};
export type JobPatch = Partial<Pick<JobRow, "status" | "note" | "completedAt" | "expiresAt" | "archivePath" | "archiveBytes" | "archiveSha256" | "attempts" | "error" | "result">> & { startedAt?: Date };

export type DataJobDeps = {
  now(): Date;
  /** oldest first: exports in `requested`; deletions in `requested` whose grace is over; ready exports past expiresAt */
  due(now: Date): Promise<{ exports: JobRow[]; deletes: JobRow[]; expired: JobRow[] }>;
  /** atomic from-status -> patch; false = someone else took it (two workers never run one job) */
  claim(id: string, from: string, patch: JobPatch): Promise<boolean>;
  update(id: string, patch: JobPatch): Promise<void>;
  collect(userId: string): Promise<{ files: { path: string; content: string }[]; counts: Record<string, number> }>;
  writeArchive(row: JobRow, files: { path: string; content: string }[]): Promise<{ path: string; bytes: number; sha256: string }>;
  removeFile(path: string): Promise<void>;
  /** paths of every archive this person has on disk (deleted with their data) */
