// Customer app grants provider (r39): the r38 Nxeon grants (per-server consent at /dashboard/connect/cyrus) seen
// through the lib/cyrus/app/grants interface. App layer on purpose: lib/cyrus may not import lib/nxeon-platform
// (host seam). Off (CYRUS_SERVER_GRANTS unset) = unavailableGrants: the UI shows the contract, no fake connection.
// SERVER ONLY.
import { grantsEnabled, grantStore, revokeGrant } from "@/lib/nxeon-platform/grants";
import { platformEventSink } from "@/lib/nxeon-platform/events";
import { unavailableGrants, type GrantScope, type GrantsProvider } from "@/lib/cyrus/app/grants";

export function appGrants(nxeonOrigin: string): GrantsProvider {
  if (!grantsEnabled()) return unavailableGrants;
  return {
    async state(userId) {
      const store = await grantStore();
      const rows = await store.listForUser("cyrus", userId);
      return {
        available: true,
        grants: rows.filter((g) => g.status === "active").map((g) => ({ serverId: g.serverId, scopes: g.scopes as GrantScope[], grantedAt: g.createdAt.toISOString(), lastUsedAt: null })),
        connectUrl: (serverId) => `${nxeonOrigin}/dashboard/connect/cyrus?server=${encodeURIComponent(serverId)}`,
      };
    },
    async revoke(userId, serverId) {
      const store = await grantStore();
      const g = await store.active("cyrus", userId, serverId);
      if (!g || g.userId !== userId) return false;
      return !!(await revokeGrant(store, { userId, grantId: g.id, by: `user:${userId}`, onEvent: platformEventSink() }));
    },
  };
}
