// Real wiring of the data export/delete jobs (./data-jobs.ts). SERVER ONLY, worker + the download route.
// HOST SEAM: Cyrus tables through cyrusDb, the account email + audit through the host, grants through the app grants
// provider (unavailable in a process that has not set one: recorded as such, never faked).
import { createHash, randomBytes } from "node:crypto";
import { mkdir, readdir, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { cyrusDb } from "../db";
import { getHost } from "../host";
import { gdprErase, gdprEraseEnabled, gdprExport, subjectValue } from "../admin/gdpr";
import { zipFiles } from "../zip";
import { grantsProvider } from "./grants";
import type { DataJobDeps, JobPatch, JobRow } from "./data-jobs";

export const exportDir = (env: Record<string, string | undefined> = process.env) => path.resolve(env.CYRUS_DATA_EXPORT_DIR?.trim() || "/var/lib/nxeon/cyrus-exports");
const json = (v: unknown) => JSON.stringify(v, (_k, x) => (typeof x === "bigint" ? x.toString() : x), 1);
const CAP = 2000;

/** A path is only ever read or removed when it sits directly inside the export dir (no traversal through a DB value). */
export function insideExportDir(p: string, env: Record<string, string | undefined> = process.env): boolean {
  const dir = exportDir(env), r = path.resolve(p);
  return path.dirname(r) === dir && /^[A-Za-z0-9_-]{1,64}-[a-f0-9]{16}\.zip$/.test(path.basename(r));
}

const README = (counts: Record<string, number>) => `Your Cyrus data export
=====================
Made by Cyrus (cyrus.my / nxeon.cloud). JSON files, one per kind of record.

export.json        what is in here, when it was made, and which tables were cut at the row cap
tables/*.json      every Cyrus row about you: projects, revisions, project assets (metadata, sha256, licence),
                   builds (metadata; jars are downloadable from the studio while the build exists), token ledger,
                   lots and plan, mod pages, posts, library contributions, notification preferences and inbox,
                   personal API keys (names, prefixes, scopes; never the secrets), server grants, data requests

Rows per table: ${Object.entries(counts).map(([k, v]) => `${k}=${v}`).join(", ") || "none"}

Your Nxeon account, servers and invoices are exported by Nxeon, not by this archive.
`;

export function dataJobDeps(env: Record<string, string | undefined> = process.env): DataJobDeps {
  const t = cyrusDb.cyrusDataRequest;
  return {
    now: () => new Date(),
    async due(now) {
      const [exports, deletes, expired] = await Promise.all([
