// r44: Cyrus data export + deletion jobs (lib/cyrus/app/data-jobs.ts) with fake deps: states, grace, erase switch,
// retries -> failed, expiry, owner-only download, cascade hooks called, audit rows, request grace on insert.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { dataJobsTick, downloadable, statusLine, DELETE_GRACE_DAYS, EXPORT_TTL_DAYS, MAX_ATTEMPTS, type DataJobDeps, type JobRow } from "../lib/cyrus/app/data-jobs";
import { memoryDataStore, requestData, DELETE_CONFIRM } from "../lib/cyrus/app/data-requests";
import { insideExportDir } from "../lib/cyrus/app/data-jobs.server";

const DAY = 86_400_000;
const T0 = new Date("2026-10-11T00:00:00Z");

function fake(rows: JobRow[], o: { erase?: boolean; collectFails?: number; eraseFails?: boolean } = {}) {
  let now = T0;
  const audits: { action: string; detail: Record<string, unknown> }[] = [];
  const removed: string[] = []; const calls: string[] = [];
  let fails = o.collectFails ?? 0;
  const d: DataJobDeps = {
    now: () => now,
    async due(n) {
      return {
        exports: rows.filter((r) => r.kind === "export" && r.status === "requested"),
        deletes: rows.filter((r) => r.kind === "delete" && r.status === "requested"),
        expired: rows.filter((r) => r.kind === "export" && r.status === "ready" && r.expiresAt! <= n),
      };
    },
    async claim(id, from, patch) { const r = rows.find((x) => x.id === id && x.status === from); if (!r) return false; Object.assign(r, patch); return true; },
    async update(id, patch) { Object.assign(rows.find((x) => x.id === id)!, patch); },
