// Cyrus product EMITTERS for the API v1 webhooks (Cyrus -> Nxeon: build.finished, mod.published, install.result,
// delivery.rolledback), the points API phase 2 left unwired. Each is best-effort and a no-op unless
// CYRUS_API_V1_WEBHOOKS=1 with a URL + dedicated secret (emitWebhook checks). The outbox is in-process (one instance)
// until the SQL proposal in prisma/manual-migration-cyrus-api-v1.sql is approved; the "cyrus-api-webhooks" sweep
// dispatches it. HOST SEAM: no Nxeon imports.
import type { ModBuild } from "@prisma/client";
import { buildFinished, createMemoryOutbox, deliveryRolledBack, dispatchWebhooks, emitWebhook, installResult, modPublished, webhookTarget, type WebhookOutbox } from "./webhooks";
import type { DeliveryResult } from "../../delivery/types";

let outbox: WebhookOutbox | null = null;
export function cyrusWebhookOutbox(): WebhookOutbox { return (outbox ??= createMemoryOutbox()); }
export function setCyrusWebhookOutboxForTests(o: WebhookOutbox | null) { outbox = o; }

const quiet = async (p: Promise<unknown>) => { try { await p; } catch (e) { console.error("[cyrus-webhooks] emit failed", (e as Error).message); } };
const on = () => !!webhookTarget();

/** A build reached succeeded/failed (lib/modbuilder/store.ts syncBuild). */
export async function emitBuildFinished(b: Pick<ModBuild, "id" | "userId" | "status" | "errorCode"> & { jarSha256?: string | null; cyrus?: unknown }): Promise<void> {
  if (!on() || (b.status !== "succeeded" && b.status !== "failed")) return;
  const projectId = ((b.cyrus ?? null) as { projectId?: string } | null)?.projectId ?? null;
  await quiet(emitWebhook(cyrusWebhookOutbox(), buildFinished({ id: b.id, userId: b.userId, status: b.status, jarSha256: b.jarSha256 ?? null, errorCode: b.errorCode ?? null, projectId })));
}
/** A mod page is public with this build (lib/cyrus-mods/pages.ts onBuildSettled). */
export async function emitModPublished(p: { userId: string; slug: string; buildId: string; version: string | null; visibility: string; publishedAt: Date | null }): Promise<void> {
  if (!on() || p.visibility === "PRIVATE" || !p.publishedAt) return;
  await quiet(emitWebhook(cyrusWebhookOutbox(), modPublished({ userId: p.userId, slug: p.slug, buildId: p.buildId, version: p.version })));
}
/** A delivery job finished (lib/cyrus/delivery/job.ts): install.result always, delivery.rolledback when it rolled back. */
export async function emitDeliveryResult(a: { userId: string; jobId: string; result: Pick<DeliveryResult, "ok" | "outcome" | "serverId" | "error" | "failedStep" | "apply"> }): Promise<void> {
  if (!on()) return;
  const r = a.result;
  await quiet(emitWebhook(cyrusWebhookOutbox(), installResult({ userId: a.userId, installId: a.jobId, serverId: r.serverId, ok: r.ok, restartRequired: r.outcome === "pending_restart" || (r.apply?.mode === "restart" && !r.apply.restarted), error: r.ok ? null : (r.error ?? r.outcome) })));
  if (r.outcome === "rolled_back" || r.outcome === "rollback_incomplete") {
    await quiet(emitWebhook(cyrusWebhookOutbox(), deliveryRolledBack({ userId: a.userId, deliveryId: a.jobId, serverId: r.serverId, failedStep: r.failedStep ?? "unknown", reason: (r.error ?? r.outcome).slice(0, 300) })));
  }
}
/** Worker sweep: one dispatch pass (no-op while off). */
export async function cyrusWebhooksSweep(): Promise<unknown> {
  const t = webhookTarget();
  if (!t) return null;
  return dispatchWebhooks({ outbox: cyrusWebhookOutbox(), target: t });
}
