-- the worker claims due rows with FOR UPDATE SKIP LOCKED, sends, then marks sent / schedules the retry / marks dead.
-- status: pending | sent | dead. Retries: 1 m, 5 m, 30 m, 2 h, 12 h, then dead (kept for an admin replay).
CREATE TABLE IF NOT EXISTS "CyrusWebhookOutbox" (
  "id"            TEXT NOT NULL,
  "type"          TEXT NOT NULL,
  "subject"       TEXT,
  "body"          TEXT NOT NULL,
  "attempts"      INTEGER NOT NULL DEFAULT 0,
  "nextAttemptAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "status"        TEXT NOT NULL DEFAULT 'pending',
  "lastError"     TEXT,
  "createdAt"     TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "sentAt"        TIMESTAMP(3),
  CONSTRAINT "CyrusWebhookOutbox_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "CyrusWebhookOutbox_due_idx" ON "CyrusWebhookOutbox"("status", "nextAttemptAt");

-- Nxeon side (receiver): processed webhook ids for exactly-once handling across instances (24 h).
CREATE TABLE IF NOT EXISTS "CyrusWebhookReceipt" (
  "id"         TEXT NOT NULL,
  "type"       TEXT NOT NULL,
  "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "CyrusWebhookReceipt_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "CyrusWebhookReceipt_receivedAt_idx" ON "CyrusWebhookReceipt"("receivedAt");
// Cyrus -> caller (Nxeon) WEBHOOKS: event builders, a transactional-outbox interface, and the dispatcher that signs,
// sends and retries. Contract: the `webhooks` section of docs/api/cyrus-v1.openapi.yaml (schemas in ./schemas.ts).
//   headers  Cyrus-Webhook-Id, Cyrus-Webhook-Timestamp (unix s), Cyrus-Signature: v1=<hex HMAC-SHA256(secret, id.ts.body)>
//            (./signing.ts signWebhook; the receiver drops anything older than 300 s and any id it has seen in 24 h)
//   delivery at-least-once; 2xx = done; anything else (or no answer in 10 s) is retried after 1 m, 5 m, 30 m, 2 h, 12 h,
//            then the event is DEAD (kept for an admin to replay). Each event carries current state, never a delta, so
//            order between events does not matter.
// OFF unless CYRUS_API_V1_WEBHOOKS=1 with a URL and a dedicated secret (>= 32 chars, never AUTH_SECRET). No product code
// emits events yet (emission points are listed in docs/CYRUS-MOVE-RUNBOOK.md); the Postgres outbox table is proposed in
// prisma/manual-migration-cyrus-api-v1.sql (NOT run). Pure apart from fetch. HOST SEAM: no Nxeon imports.
import { randomBytes } from "node:crypto";
import { signWebhook } from "./signing";
import type { WebhookEvent } from "./schemas";

export const WEBHOOK_RETRY_DELAYS_MS = [60_000, 5 * 60_000, 30 * 60_000, 2 * 3600_000, 12 * 3600_000] as const;
export const WEBHOOK_TIMEOUT_MS = 10_000;

export type WebhookEnvelope<D = Record<string, unknown>> = { id: string; type: WebhookEvent; createdAt: string; subject: string | null; data: D };
export type OutboxRow = { id: string; type: WebhookEvent; subject: string | null; body: string; attempts: number; nextAttemptAt: Date; status: "pending" | "sent" | "dead"; lastError: string | null; createdAt: Date };

export interface WebhookOutbox {
  /** Record the event (in the same transaction as the change it describes, for the Postgres outbox). Idempotent by id. */
  add(e: WebhookEnvelope): Promise<void>;
  /** Pending events whose time has come, oldest first. A multi-worker store claims them (FOR UPDATE SKIP LOCKED). */
  due(now: Date, limit: number): Promise<OutboxRow[]>;
  markSent(id: string, now: Date): Promise<void>;
  markFailed(id: string, a: { attempts: number; nextAttemptAt: Date | null; error: string }): Promise<void>;
}

export type WebhookTarget = { url: string; secret: string };
