// Cyrus analytics + consent (r40): cookie consent for cyrus.my, privacy-safe attribution / referral capture, and the
// conversion-event spec for Meta and Google. PURE and client-safe (no imports, no network): the banner, the static
// landing script (public/cyrus/consent.js mirrors these rules) and the server all use these functions.
// Flags (all OFF): CYRUS_CONSENT (banner), CYRUS_ATTRIBUTION (store attribution), CYRUS_CONVERSIONS (send events).
// Rules:
//   - nothing optional is stored before a choice; "Reject all" is as easy as "Accept all"; the choice lasts 180 days
//   - referral code + UTM tags need ANALYTICS consent; ad click ids (fbclid, gclid) need MARKETING consent
//   - no third-party cookies: attribution crosses cyrus.my -> nxeon.cloud as a validated query parameter on the SSO
//     hand-off (r36), and is re-validated on arrival like any URL input
//   - conversion payloads carry no raw personal data: an email only as a SHA-256 the caller computed, nothing else

export const CYRUS_CONSENT_COOKIE = "cyrus_consent";
export const CYRUS_ATTR_COOKIE = "cyrus_attr";
export const CONSENT_MAX_AGE_S = 180 * 86_400;
export const ATTR_MAX_AGE_S = 30 * 86_400;
export const CONSENT_VERSION = 1;

export type Consent = { analytics: boolean; marketing: boolean; at: number; v: number };

export function serializeConsent(c: { analytics: boolean; marketing: boolean }, nowMs: number): string {
  return `v${CONSENT_VERSION}.a${c.analytics ? 1 : 0}.m${c.marketing ? 1 : 0}.${Math.floor(nowMs / 1000)}`;
}

/** null = no valid choice yet (show the banner). An older version also counts as no choice (ask again). */
export function parseConsent(raw: string | null | undefined): Consent | null {
  const m = /^v(\d+)\.a([01])\.m([01])\.(\d{9,11})$/.exec(raw ?? "");
  if (!m || Number(m[1]) !== CONSENT_VERSION) return null;
  return { v: Number(m[1]), analytics: m[2] === "1", marketing: m[3] === "1", at: Number(m[4]) * 1000 };
}

export type Attribution = { ref?: string; utm?: { source?: string; medium?: string; campaign?: string; content?: string; term?: string }; click?: { fbclid?: string; gclid?: string }; landing?: string; at?: number };

const REF = /^[A-Za-z0-9_-]{2,32}$/;
const UTM = /^[A-Za-z0-9 ._+:/-]{1,80}$/;
const CLICK = /^[A-Za-z0-9._-]{8,200}$/;
const PATH = /^\/[A-Za-z0-9/_-]{0,80}$/;

/** What a landing URL carries (everything validated; anything odd is dropped, never stored). */
export function parseLanding(params: URLSearchParams | Record<string, string | undefined>, path = "/"): Attribution {
  const get = (k: string) => (params instanceof URLSearchParams ? params.get(k) : params[k]) ?? undefined;
  const a: Attribution = {};
  const ref = get("ref") ?? get("partner");
  if (ref && REF.test(ref)) a.ref = ref;
  const utm: NonNullable<Attribution["utm"]> = {};
  for (const k of ["source", "medium", "campaign", "content", "term"] as const) { const v = get(`utm_${k}`); if (v && UTM.test(v)) utm[k] = v; }
  if (Object.keys(utm).length) a.utm = utm;
  const click: NonNullable<Attribution["click"]> = {};
  for (const k of ["fbclid", "gclid"] as const) { const v = get(k); if (v && CLICK.test(v)) click[k] = v; }
  if (Object.keys(click).length) a.click = click;
  if (PATH.test(path)) a.landing = path;
  return a;
}

/** Keep only what the person consented to (no consent = nothing). */
export function allowedAttribution(a: Attribution, c: Consent | null): Attribution | null {
  if (!c || (!c.analytics && !c.marketing)) return null;
  const out: Attribution = {};
  if (c.analytics) { if (a.ref) out.ref = a.ref; if (a.utm) out.utm = a.utm; if (a.landing) out.landing = a.landing; }
  if (c.marketing && a.click) out.click = a.click;
  if (!Object.keys(out).length) return null;
  out.at = a.at ?? Date.now();
  return out;
}

/** First touch wins for 30 days, except a NEW referral code (an explicit partner link) replaces the old one. */
export function mergeAttribution(prev: Attribution | null, next: Attribution | null, nowMs: number): Attribution | null {
  if (!next) return prev;
  if (!prev || !prev.at || nowMs - prev.at > ATTR_MAX_AGE_S * 1000) return next;
  return { ...prev, ...(next.ref && next.ref !== prev.ref ? { ref: next.ref } : {}), click: { ...next.click, ...prev.click } };
}

const b64u = (s: string) => (typeof btoa === "function" ? btoa(unescape(encodeURIComponent(s))) : Buffer.from(s, "utf8").toString("base64")).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const unb64u = (s: string) => { const t = s.replace(/-/g, "+").replace(/_/g, "/"); return typeof atob === "function" ? decodeURIComponent(escape(atob(t))) : Buffer.from(t, "base64").toString("utf8"); };

/** Cookie / hand-off encoding (base64url JSON, at most 1 KiB). */
export function encodeAttribution(a: Attribution): string | null {
  const s = b64u(JSON.stringify(a));
  return s.length <= 1024 ? s : null;
}

/** Decode AND re-validate (an arriving value is untrusted input). */
export function decodeAttribution(raw: string | null | undefined): Attribution | null {
  if (!raw || raw.length > 1024 || !/^[A-Za-z0-9_-]+$/.test(raw)) return null;
  let v: unknown;
  try { v = JSON.parse(unb64u(raw)); } catch { return null; }
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  const flat: Record<string, string> = {};
  if (typeof o.ref === "string") flat.ref = o.ref;
  const utm = o.utm && typeof o.utm === "object" ? (o.utm as Record<string, unknown>) : {};
  for (const k of ["source", "medium", "campaign", "content", "term"]) if (typeof utm[k] === "string") flat[`utm_${k}`] = utm[k] as string;
  const click = o.click && typeof o.click === "object" ? (o.click as Record<string, unknown>) : {};
  for (const k of ["fbclid", "gclid"]) if (typeof click[k] === "string") flat[k] = click[k] as string;
  const a = parseLanding(flat, typeof o.landing === "string" ? o.landing : "/");
  if (typeof o.at === "number" && Number.isFinite(o.at)) a.at = o.at;
  if (typeof o.landing !== "string") delete a.landing;
  return Object.keys(a).filter((k) => k !== "at").length ? a : null;
}

// ---------------------------------------------------------------------------
// Conversion events (spec). Sending is NOT built here: CYRUS_CONVERSIONS gates a future sender, which reuses Nxeon's
// Meta CAPI / Google Ads offline-conversion plumbing (lib/google-ads.ts). These are the payloads it would send.
// ---------------------------------------------------------------------------

export type ConversionId = "sign_up" | "first_build" | "purchase";
export const CONVERSION_EVENTS: { id: ConversionId; meta: string; google: string; when: string; value: boolean }[] = [
  { id: "sign_up", meta: "CompleteRegistration", google: "sign_up", when: "A Cyrus sign-up via Nxeon completes (r36 consent sign-up).", value: false },
  { id: "first_build", meta: "CyrusFirstBuild", google: "cyrus_first_build", when: "The account's first build succeeds.", value: false },
  { id: "purchase", meta: "Purchase", google: "purchase", when: "A paid top-up or plan invoice is credited (live mode only).", value: true },
];

export type ConversionInput = { id: ConversionId; eventId: string; atMs: number; consent: Consent | null; attribution: Attribution | null; valueCents?: number | null; currency?: string; emailSha256?: string | null; sourceUrl?: string };

/** The Meta CAPI and Google payloads for one event, or null when marketing consent is missing (then nothing is sent). */
export function conversionPayload(i: ConversionInput): { meta: Record<string, unknown>; google: Record<string, unknown> } | null {
  if (!i.consent?.marketing) return null;
  const def = CONVERSION_EVENTS.find((e) => e.id === i.id);
  if (!def || !/^[A-Za-z0-9:_-]{6,120}$/.test(i.eventId)) return null;
  const value = def.value && typeof i.valueCents === "number" && i.valueCents > 0 ? i.valueCents / 100 : undefined;
  const email = i.emailSha256 && /^[0-9a-f]{64}$/.test(i.emailSha256) ? i.emailSha256 : undefined;
  const t = Math.floor(i.atMs / 1000);
  const fbclid = i.attribution?.click?.fbclid;
  return {
    meta: {
      event_name: def.meta, event_time: t, event_id: i.eventId, action_source: "website", ...(i.sourceUrl ? { event_source_url: i.sourceUrl } : {}),
      user_data: { ...(email ? { em: [email] } : {}), ...(fbclid ? { fbc: `fb.1.${i.atMs}.${fbclid}` } : {}) },
      ...(value !== undefined ? { custom_data: { value, currency: i.currency ?? "USD" } } : {}),
    },
    google: {
      conversion_action: def.google, conversion_date_time: new Date(i.atMs).toISOString(), order_id: i.eventId,
      ...(i.attribution?.click?.gclid ? { gclid: i.attribution.click.gclid } : {}), ...(email ? { user_identifiers: [{ hashed_email: email }] } : {}),
      ...(value !== undefined ? { conversion_value: value, currency_code: i.currency ?? "USD" } : {}),
    },
  };
}

