// Cyrus one-account bridge: the handshake's pure rules (parameter checks, URLs, error codes). HOST SEAM: no Nxeon imports.
//
//   Sign in with Nxeon (cyrus.my):  /auth/nxeon/start -> Nxeon /sso/cyrus/authorize (login / register + consent,
//     verified email) -> /auth/nxeon/callback?code=<Ed25519 assertion>&state -> Cyrus session cookie.
//   Sign in with Cyrus (nxeon.cloud): /sso/cyrus/start -> cyrus.my /auth/handoff (needs a Cyrus session, which itself
//     came from Nxeon) -> Nxeon /sso/cyrus/return -> Nxeon session. Same account both ways: sub = the account id.
import { callbackUrls, type BridgeConfig } from "./config";
import { NONCE_RE } from "./assertion-rules";

export type ClientId = "cyrus" | "nxeon";
export type Prompt = "login" | "create";
export type AuthorizeParams = { clientId: ClientId; redirectUri: string; state: string; nonce: string; prompt: Prompt };

/** Exact client + exact redirect_uri + well-formed state/nonce, or null (the caller answers 400, never redirects). */
export function parseAuthorize(q: URLSearchParams, expect: ClientId, cfg: BridgeConfig): AuthorizeParams | null {
  const clientId = q.get("client_id"), redirectUri = q.get("redirect_uri"), state = q.get("state") ?? "", nonce = q.get("nonce") ?? "";
  if (clientId !== expect) return null;
  if (redirectUri !== callbackUrls(cfg)[expect]) return null;
  if (!NONCE_RE.test(state) || !NONCE_RE.test(nonce)) return null;
  const p = q.get("prompt");
  return { clientId: expect, redirectUri, state, nonce, prompt: p === "create" ? "create" : "login" };
}

export function authorizeQuery(p: AuthorizeParams): string {
  const q = new URLSearchParams({ client_id: p.clientId, redirect_uri: p.redirectUri, state: p.state, nonce: p.nonce });
  if (p.prompt === "create") q.set("prompt", "create");
  return q.toString();
}

/** Back to the (vetted) redirect_uri with a code or an error code, plus the caller's state. */
import { callbackUrls } from "@/lib/cyrus/bridge/config";
import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
import { authorizeQuery } from "@/lib/cyrus/bridge/flow";
import { beginHandshake, bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/** cyrus.my -> Nxeon authorize, with a fresh state + nonce sealed into a host-only cookie on cyrus.my. */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "cyrus");
  if (!cfg) return notFound();
  if (limited(req, "start")) return go(`${cfg.cyrusOrigin}/sign-in?error=ratelimited`);
  const sp = new URL(req.url).searchParams;
  const mode = sp.get("mode") === "create" ? "create" : undefined;
  const st = await beginHandshake("cyrus", safeCyrusNext(sp.get("next")), mode);
  const q = authorizeQuery({ clientId: "cyrus", redirectUri: callbackUrls(cfg).cyrus, state: st.s, nonce: st.n, prompt: mode ?? "login" });
  return go(`${cfg.nxeonOrigin}/sso/cyrus/authorize?${q}`);
}
import { currentUser, currentSessionTokenHash, impersonating } from "@/lib/auth";
import { parseAuthorize, authorizeQuery, callbackUrl } from "@/lib/cyrus/bridge/flow";
import { mintAssertion, privateKeyFor } from "@/lib/cyrus/bridge/assertion";
import { bridgeEmailBlocked, bridgeGate, go, grantConsent, hasConsent, limited, notFound } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/**
 * "Sign in with Nxeon" for cyrus.my (CYRUS_DOMAIN_MODE). Nxeon is the identity provider:
 *   ?client_id=cyrus&redirect_uri=<exact cyrus callback>&state&nonce[&prompt=create]
 * Not signed in -> /login (or the consent + /register path for prompt=create), back here after. Signed in, verified
 * email, consent given -> a 90 s Ed25519 assertion (sub = account id, the caller's nonce, this session's hash) to the
 * EXACT callback. Bad client / redirect_uri -> 400, never a redirect. Impersonation never crosses hosts.
 */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "nxeon");
  if (!cfg) return notFound();
  const url = new URL(req.url);
  const p = parseAuthorize(url.searchParams, "cyrus", cfg);
  if (!p) return Response.json({ error: "invalid_request" }, { status: 400 });
  if (limited(req, "authorize")) return go(callbackUrl(p, { error: "ratelimited" }));
  if (await impersonating()) return go(callbackUrl(p, { error: "impersonating" }));

  const self = `/sso/cyrus/authorize?${authorizeQuery(p)}`;
  const consentPage = (extra = "") => go(`${cfg.nxeonOrigin}/sso/cyrus/consent?${authorizeQuery(p)}${extra}`);
  const user = await currentUser();
  if (!user) {
    // Sign-up: consent comes first (it explains that a Cyrus account IS a Nxeon account), then /register.
    if (p.prompt === "create" && !(await hasConsent("", p.nonce))) return consentPage();
    const page = p.prompt === "create" ? "/register" : "/login";
    return go(`${cfg.nxeonOrigin}${page}?next=${encodeURIComponent(self)}`);
  }
  if (await bridgeEmailBlocked(user)) return consentPage("&verify=1");
  if (!(await hasConsent(user.id, p.nonce))) return consentPage();
  await grantConsent({ userId: user.id }); // a sign-up's one-handshake grant becomes the account's remembered consent

  const code = mintAssertion({
    typ: "login", iss: cfg.nxeonOrigin, aud: cfg.cyrusOrigin, sub: user.id, nonce: p.nonce, sid: await currentSessionTokenHash(),
  }, privateKeyFor("nxeon"));
  return go(callbackUrl(p, { code }));
}

