// Multi-worker safe: due() CLAIMS rows (FOR UPDATE SKIP LOCKED) by pushing nextAttemptAt out by a lease, so a second
// dispatcher never sends the same row while the first is still waiting on it; markSent/markFailed end the lease.
// Delivery stays at-least-once (a crash after the POST re-sends after the lease); receivers dedupe by event id.
// HOST SEAM: raw SQL through the db handle the caller passes (cyrusDb in ./emit.ts).
import type { OutboxRow, WebhookOutbox } from "./webhooks";

export type RawSql = { $queryRawUnsafe<T = unknown>(q: string, ...a: unknown[]): Promise<T>; $executeRawUnsafe(q: string, ...a: unknown[]): Promise<number> };
export const OUTBOX_LEASE_MS = 2 * 60_000;
const T = `"CyrusWebhookOutbox"`;
type Raw = { id: string; type: string; subject: string | null; body: string; attempts: number | bigint; nextAttemptAt: Date; status: string; lastError: string | null; createdAt: Date };
const row = (r: Raw): OutboxRow => ({ id: r.id, type: r.type as OutboxRow["type"], subject: r.subject, body: r.body, attempts: Number(r.attempts), nextAttemptAt: new Date(r.nextAttemptAt), status: r.status as OutboxRow["status"], lastError: r.lastError, createdAt: new Date(r.createdAt) });

export function createSqlWebhookOutbox(db: RawSql, leaseMs = OUTBOX_LEASE_MS): WebhookOutbox {
  return {
    async add(e) {
      await db.$executeRawUnsafe(`INSERT INTO ${T} ("id","type","subject","body","nextAttemptAt","createdAt") VALUES ($1,$2,$3,$4,$5,$5) ON CONFLICT ("id") DO NOTHING`, e.id, e.type, e.subject, JSON.stringify(e), new Date(e.createdAt));
    },
    async due(now, limit) {
      const rows = await db.$queryRawUnsafe<Raw[]>(
        `UPDATE ${T} o SET "nextAttemptAt" = $3 FROM (SELECT "id" FROM ${T} WHERE "status" = 'pending' AND "nextAttemptAt" <= $1 ORDER BY "createdAt" ASC LIMIT $2 FOR UPDATE SKIP LOCKED) d
         WHERE o."id" = d."id" RETURNING o."id", o."type", o."subject", o."body", o."attempts", o."nextAttemptAt", o."status", o."lastError", o."createdAt"`,
        now, Math.max(1, Math.min(500, limit)), new Date(now.getTime() + leaseMs));
      return rows.map(row).sort((a, b) => +a.createdAt - +b.createdAt);
    },
    async markSent(id, now) { await db.$executeRawUnsafe(`UPDATE ${T} SET "status" = 'sent', "lastError" = NULL, "sentAt" = $2 WHERE "id" = $1`, id, now); },
    async markFailed(id, f) {
      await db.$executeRawUnsafe(`UPDATE ${T} SET "attempts" = $2, "lastError" = $3, "nextAttemptAt" = COALESCE($4::timestamp, "nextAttemptAt"), "status" = CASE WHEN $4::timestamp IS NULL THEN 'dead' ELSE 'pending' END WHERE "id" = $1`, id, f.attempts, f.error, f.nextAttemptAt);
    },
  };
}

export type OutboxMetrics = { pending: number; dead: number; sent24h: number; failedAttempts24h: number; oldestPendingAgeSec: number | null; byType: Record<string, { pending: number; dead: number }> };

/** Metrics for the admin reconciliation view and alerts (computed in SQL, so every process sees the same numbers). */
export async function outboxMetrics(db: RawSql, now = new Date()): Promise<OutboxMetrics> {
  const since = new Date(now.getTime() - 86_400_000);
  const [agg] = await db.$queryRawUnsafe<{ pending: bigint | number; dead: bigint | number; sent24h: bigint | number; failed24h: bigint | number; oldest: Date | null }[]>(
    `SELECT COUNT(*) FILTER (WHERE "status" = 'pending') AS pending, COUNT(*) FILTER (WHERE "status" = 'dead') AS dead,
            COUNT(*) FILTER (WHERE "status" = 'sent' AND "sentAt" >= $1) AS sent24h,
            COUNT(*) FILTER (WHERE "lastError" IS NOT NULL AND "createdAt" >= $1) AS failed24h,
            MIN("createdAt") FILTER (WHERE "status" = 'pending') AS oldest FROM ${T}`, since);
  const types = await db.$queryRawUnsafe<{ type: string; status: string; n: bigint | number }[]>(`SELECT "type", "status", COUNT(*) AS n FROM ${T} WHERE "status" IN ('pending','dead') GROUP BY "type", "status"`);
  const byType: OutboxMetrics["byType"] = {};
  for (const t of types) { const b = (byType[t.type] ??= { pending: 0, dead: 0 }); if (t.status === "pending") b.pending = Number(t.n); else b.dead = Number(t.n); }
  return {
    pending: Number(agg?.pending ?? 0), dead: Number(agg?.dead ?? 0), sent24h: Number(agg?.sent24h ?? 0), failedAttempts24h: Number(agg?.failed24h ?? 0),
    oldestPendingAgeSec: agg?.oldest ? Math.max(0, Math.round((now.getTime() - new Date(agg.oldest).getTime()) / 1000)) : null, byType,
  };
}
