/** r44: receipts in Postgres ("CyrusWebhookReceipt", prisma/manual-migration-cyrus-api-v1.sql) so every Nxeon instance
 *  sees the same processed ids: exactly-once handling across instances for 24 h (older rows are pruned on claim). */
export function createSqlReceipts(db: { $executeRawUnsafe(q: string, ...a: unknown[]): Promise<number> }, ttlMs = 24 * 3600_000): ReceiptStore {
  let lastPrune = 0;
  return {
    async claim(id, type, now) {
      if (now - lastPrune > 3600_000) { lastPrune = now; await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookReceipt" WHERE "receivedAt" < $1`, new Date(now - ttlMs)).catch(() => 0); }
      return (await db.$executeRawUnsafe(`INSERT INTO "CyrusWebhookReceipt" ("id","type","receivedAt") VALUES ($1,$2,$3) ON CONFLICT ("id") DO NOTHING`, id, type, new Date(now))) === 1;
    },
    async release(id) { await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookReceipt" WHERE "id" = $1`, id); },
  };
}
EOF
sed -i 's|export { receiveCyrusWebhook, createMemoryReceipts,|export { receiveCyrusWebhook, createMemoryReceipts, createSqlReceipts,|' lib/cyrus-client/index.ts
mkdir -p app/api/platform/cyrus/webhooks; cat > app/api/platform/cyrus/webhooks/route.ts <<'EOF'
// r44 NXEON SIDE: the receiver for Cyrus -> Nxeon API v1 webhooks (build.finished, mod.published, install.result,
// delivery.rolledback, library.contributed). Off unless CYRUS_API_V1_WEBHOOK_RECEIVER=1 (404 otherwise, as if absent).
// Signature (v1 HMAC over id.timestamp.body, current + previous secret), 300 s timestamp window and id replay
// protection live in lib/cyrus-client/webhook-receiver.ts; receipts are SQL when CYRUS_API_V1_WEBHOOK_STORE=sql.
// What Nxeon does with an event today: one audit row (cyrus.webhook.<type>). Product reactions are owner decisions.
import { db } from "@/lib/db";
import { createMemoryReceipts, createSqlReceipts, receiveCyrusWebhook, type ReceiptStore } from "@/lib/cyrus-client";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

let mem: ReceiptStore | null = null;
const receipts = () => (process.env.CYRUS_API_V1_WEBHOOK_STORE === "sql" ? createSqlReceipts(db) : (mem ??= createMemoryReceipts()));

export async function POST(req: Request) {
  if (process.env.CYRUS_API_V1_WEBHOOK_RECEIVER !== "1") return new Response("Not found", { status: 404 });
  const secrets = [process.env.CYRUS_API_V1_WEBHOOK_SECRET, process.env.CYRUS_API_V1_WEBHOOK_SECRET_PREVIOUS].filter((s): s is string => !!s && s !== process.env.AUTH_SECRET);
  return receiveCyrusWebhook(req, {
    secrets, receipts: receipts(), log: (m) => console.error(m),
    handle: async (e) => {
      const subject = typeof e.subject === "string" && /^[A-Za-z0-9_-]{1,64}$/.test(e.subject) ? e.subject : null;
      await db.auditLog.create({ data: { userId: subject, action: `cyrus.webhook.${e.type}`, detail: JSON.stringify({ id: e.id, data: e.data }).slice(0, 2000) } });
    },
  });
}
EOF
