);
CREATE TABLE IF NOT EXISTS "CyrusConversion" (
  "id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "kind" TEXT NOT NULL, "valueCents" INTEGER, "currency" TEXT,
  "status" TEXT NOT NULL DEFAULT 'pending', "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "sentAt" TIMESTAMP(3)
);
CREATE INDEX IF NOT EXISTS "CyrusConversion_status_createdAt_idx" ON "CyrusConversion"("status", "createdAt");
