cat > test/cyrus-bridge-gaps.test.ts <<'EOF'
// r44 (3): conversion sender (consent, transport, retries, dedupe id), attribution hand-off (flow attr param,
// partner-code receiver), webhook outbox selection. Fakes only; the SQL parts are in cyrus-bridge-gaps-db.test.ts.
import "./_cyrus-server-only-shim";
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { conversionSweep, conversionEventId, recordConversion, type ConversionDeps, type ConversionRow } from "../lib/cyrus/analytics/conversions";
import { encodeAttribution, serializeConsent } from "../lib/cyrus/analytics/consent";
import { authorizeQuery, cleanAttr, parseAuthorize } from "../lib/cyrus/bridge/flow";
import { partnerCodeFrom } from "../lib/cyrus-bridge/attribution";

const ON = { CYRUS_CONVERSIONS: "1" };
const NOW = Date.parse("2026-10-11T10:00:00Z");
function deps(o: { consent?: string | null; attr?: string | null; transport?: ConversionDeps["transport"] } = {}) {
  const rows: (ConversionRow & { lastError?: string | null })[] = [];
  const sent: Record<string, unknown>[] = [];
  const d: ConversionDeps = {
    async insert(r) { if (rows.some((x) => x.id === r.id)) return false; rows.push({ ...r, status: "pending", attempts: 0, createdAt: new Date(NOW) }); return true; },
    async due() { return rows.filter((r) => r.status === "pending"); },
    async mark(id, p) { Object.assign(rows.find((r) => r.id === id)!, p); },
    async snapshot() { return o.consent === undefined ? { consent: serializeConsent({ analytics: true, marketing: true }, NOW), attr: o.attr ?? null } : { consent: o.consent, attr: o.attr ?? null }; },
    async emailSha256() { return "a".repeat(64); },
    transport: o.transport === undefined ? { meta: async (e) => { sent.push(e); return true; }, google: async () => false } : o.transport,
  };
  return { d, rows, sent };
}

describe("r44 conversion sender", () => {
  it("off: records nothing and sends nothing", async () => {
    const { d, rows } = deps();
    assert.equal(await recordConversion({ id: "sign_up", key: "u1", userId: "u1" }, d, {}), false);
    assert.deepEqual(await conversionSweep(d, {}), { sent: 0, skipped: 0, retried: 0, failed: 0 });
    assert.equal(rows.length, 0);
  });
  it("one event per deterministic id; sent with marketing consent, payload is the r40 spec", async () => {
    const { d, rows, sent } = deps({ attr: encodeAttribution({ click: { fbclid: "fbclid12345" } }) });
    assert.equal(await recordConversion({ id: "purchase", key: "inv_1", userId: "u1", valueCents: 1500 }, d, ON), true);
    assert.equal(await recordConversion({ id: "purchase", key: "inv_1", userId: "u1", valueCents: 1500 }, d, ON), false);
    const r = await conversionSweep(d, ON);
    assert.equal(r.sent, 1); assert.equal(rows[0].status, "sent"); assert.equal(rows[0].id, conversionEventId("purchase", "inv_1"));
    assert.equal(sent[0].event_name, "Purchase"); assert.deepEqual((sent[0] as any).custom_data, { value: 15, currency: "USD" });
    assert.ok(String((sent[0] as any).user_data.fbc).endsWith("fbclid12345"));
  });
  it("no marketing consent (or no snapshot): closed as skipped:no_consent, never sent", async () => {
    for (const consent of [serializeConsent({ analytics: true, marketing: false }, NOW), null]) {
      const { d, rows, sent } = deps({ consent });
      await recordConversion({ id: "sign_up", key: "u1", userId: "u1" }, d, ON);
      await conversionSweep(d, ON);
      assert.equal(rows[0].status, "skipped:no_consent"); assert.equal(sent.length, 0);
    }
  });
  it("no host transport: skipped:no_transport; transport refusing: retried then failed", async () => {
    const a = deps({ transport: null });
    await recordConversion({ id: "sign_up", key: "u1", userId: "u1" }, a.d, ON); await conversionSweep(a.d, ON);
    assert.equal(a.rows[0].status, "skipped:no_transport");
    const b = deps({ transport: { meta: async () => false, google: async () => { throw new Error("x"); } } });
    await recordConversion({ id: "first_build", key: "u1", userId: "u1" }, b.d, ON);
    for (let i = 0; i < 3; i++) await conversionSweep(b.d, ON);
    assert.equal(b.rows[0].status, "failed"); assert.equal(b.rows[0].attempts, 3);
  });
});

describe("r44 attribution hand-off", () => {
  const cfg = { cyrusOrigin: "https://cyrus.my", nxeonOrigin: "https://nxeon.cloud" } as any;
  it("attr survives parse/query only when valid; junk is dropped", () => {
    const attr = encodeAttribution({ ref: "SAMCODE", at: 1 })!;
    assert.equal(cleanAttr(attr), attr);
    assert.equal(cleanAttr("%%%"), undefined);
    assert.equal(cleanAttr(Buffer.from(JSON.stringify({ ref: "<script>" })).toString("base64url")), undefined);
    const q = authorizeQuery({ clientId: "cyrus", redirectUri: "https://cyrus.my/auth/nxeon/callback", state: "s".repeat(32), nonce: "n".repeat(32), prompt: "create", attr });
    assert.ok(q.includes("attr="));
    const p = parseAuthorize(new URLSearchParams(q), "cyrus", { ...cfg, callbackOverride: undefined });
    if (p) assert.equal(p.attr, attr); // null only when the test config's callback differs; the attr rule is what matters
  });
  it("partner code: upper-cased, validated, not re-applied when the same code is already set", () => {
    const attr = encodeAttribution({ ref: "sam_01" })!;
    assert.equal(partnerCodeFrom(attr, null), "SAM_01");
