    const attr = encodeAttribution({ ref: "sam_01" })!;
    assert.equal(partnerCodeFrom(attr, null), "SAM_01");
    assert.equal(partnerCodeFrom(attr, "sam_01"), null);
    assert.equal(partnerCodeFrom(attr, "OTHER"), "SAM_01");
    assert.equal(partnerCodeFrom(encodeAttribution({ utm: { source: "x" } }), null), null);
    assert.equal(partnerCodeFrom(null, null), null);
  });
});
