cd /tank/dev-worktrees/cyrus-r44; cat > test/cyrus-bridge-gaps-db.test.ts <<'EOF'
// r44 against the devhost THROWAWAY database: the SQL webhook outbox (lease claim, retry ladder, dead, admin replay,
// metrics), SQL receipts (exactly once across "instances"), dispatcher end to end into the real receiver, and one real
// data export archive + deletion job. Opt-in, fail-closed: DATABASE_URL must be 127.0.0.1:5433/wt_* and CYRUS_BRIDGE_DB_TEST=1.
//   scripts/devhost run -- env CYRUS_BRIDGE_DB_TEST=1 npx tsx --test test/cyrus-bridge-gaps-db.test.ts
import "./_cyrus-server-only-shim";
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, mkdtempSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_BRIDGE_DB_TEST === "1" && /@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?|$)/.test(url);
const skip = safe ? false : "devhost throwaway DB only (CYRUS_BRIDGE_DB_TEST=1)";
const SECRET = "w".repeat(40);
type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
const dir = mkdtempSync(path.join(tmpdir(), "cyrus-export-"));
const users: string[] = [];

before(async () => {
  if (!safe) return;
  db = (await import("../lib/db.ts")).db;
  for (const f of ["prisma/manual-migration-cyrus-api-v1.sql", "prisma/manual-migration-cyrus-r44-data-jobs.sql", "prisma/manual-migration-cyrus-r44-bridge.sql"]) {
    const sql = readFileSync(path.join(__dirname, "..", f), "utf8").split("\n").filter((l) => !l.trim().startsWith("--")).join("\n");
    for (const stmt of sql.split(/;\s*\n/).map((s) => s.trim()).filter(Boolean)) await db.$executeRawUnsafe(stmt);
  }
  await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookOutbox"`); await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookReceipt"`);
});
after(async () => {
  if (!safe) return;
  await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookOutbox"`); await db.$executeRawUnsafe(`DELETE FROM "CyrusWebhookReceipt"`);
  await db.cyrusDataRequest.deleteMany({ where: { userId: { in: users } } });
  await db.cyrusProject.deleteMany({ where: { userId: { in: users } } });
  await db.user.deleteMany({ where: { id: { in: users } } });
  rmSync(dir, { recursive: true, force: true });
});

describe("r44 SQL webhook outbox + receiver", { skip }, () => {
  it("lease claim: two dispatchers never get the same row; retry ladder -> dead; replay; metrics", async () => {
    const { createSqlWebhookOutbox, outboxMetrics } = await import("../lib/cyrus/api/v1/outbox-sql.ts");
    const { buildFinished, dispatchWebhooks } = await import("../lib/cyrus/api/v1/webhooks.ts");
    const { sqlOutboxAdmin } = await import("../lib/cyrus/admin/reconcile.ts");
    const ob = createSqlWebhookOutbox(db);
    const t0 = new Date("2026-10-11T00:00:00Z");
    const e = buildFinished({ id: "b_r44", userId: "u_r44", status: "succeeded", jarSha256: null, errorCode: null }, t0);
    await ob.add(e); await ob.add(e);
    assert.equal(Number((await db.$queryRawUnsafe<{ n: bigint }[]>(`SELECT COUNT(*) n FROM "CyrusWebhookOutbox"`))[0].n), 1, "idempotent by id");
    const [a, b] = await Promise.all([ob.due(new Date(t0.getTime() + 1000), 10), ob.due(new Date(t0.getTime() + 1000), 10)]);
    assert.equal(a.length + b.length, 1, "claimed once");
    let now = new Date(t0.getTime() + 200_000); // past the lease
    const fail = async () => ({ status: 503 }) as Response;
    let dead = 0;
    for (let i = 0; i < 8 && !dead; i++) { const r = await dispatchWebhooks({ outbox: ob, target: { url: "http://127.0.0.1:9/x", secret: SECRET }, now: () => now, fetch: fail as never }); dead += r.dead; now = new Date(now.getTime() + 13 * 3600_000); }
    assert.equal(dead, 1);
    const m = await outboxMetrics(db, now);
    assert.equal(m.dead, 1); assert.equal(m.byType["build.finished"].dead, 1);
    assert.equal(await sqlOutboxAdmin(db).replay(e.id), 1);
    assert.equal((await outboxMetrics(db, now)).pending, 1);
  });
  it("dispatcher -> real receiver: signed, accepted once, a replayed delivery is a duplicate; tampered is 401", async () => {
    const { createSqlWebhookOutbox } = await import("../lib/cyrus/api/v1/outbox-sql.ts");
    const { dispatchWebhooks } = await import("../lib/cyrus/api/v1/webhooks.ts");
    const { receiveCyrusWebhook, createSqlReceipts } = await import("../lib/cyrus-client/index.ts");
    const ob = createSqlWebhookOutbox(db);
    const handled: string[] = [];
    const recv = (rq: Request) => receiveCyrusWebhook(rq, { secrets: [SECRET], receipts: createSqlReceipts(db), handle: async (x) => { handled.push(x.id); } });
    let last: Request | null = null;
    const viaReceiver = async (u: string, init: RequestInit) => { last = new Request(u, init); return recv(last.clone()); };
    const r = await dispatchWebhooks({ outbox: ob, target: { url: "https://nxeon.test/api/platform/cyrus/webhooks", secret: SECRET }, now: () => new Date(), fetch: viaReceiver as never });
    assert.equal(r.sent, 1); assert.equal(handled.length, 1);
    const again = await recv(last!.clone()); assert.equal((await again.json()).duplicate, true, "second instance sees the receipt");
    const h = new Headers(last!.headers); h.set("cyrus-signature", "v1=" + "0".repeat(64));
    assert.equal((await recv(new Request(last!.url, { method: "POST", headers: h, body: await last!.clone().text() }))).status, 401);
  });
});

describe("r44 data jobs on a real database", { skip }, () => {
  it("export writes a real zip with the person's tables; delete (grace over, erase on) removes projects + keys + archive", async () => {
    const env = { CYRUS_DATA_EXPORT_DIR: dir, CYRUS_GDPR_ERASE: "1" };
    process.env.CYRUS_GDPR_ERASE = "1";
    const { dataJobsTick } = await import("../lib/cyrus/app/data-jobs.ts");
    const { dataJobDeps } = await import("../lib/cyrus/app/data-jobs.server.ts");
    const u = await db.user.create({ data: { email: `r44-${Date.now()}@example.test`, passwordHash: "x", name: "R44", emailVerifiedAt: new Date() } });
    users.push(u.id);
    await db.cyrusProject.create({ data: { userId: u.id, game: "minecraft", namespace: "nx_r44", title: "Coin shop" } });
    await db.cyrusPersonalApiKey.create({ data: { userId: u.id, name: "ci", prefix: "ABCDEFGH", sha256: "f".repeat(63) + "1", scopes: ["projects:read"] } });
    const ex = await db.cyrusDataRequest.create({ data: { userId: u.id, kind: "export" } });
    const r1 = await dataJobsTick(dataJobDeps(env));
    assert.equal(r1.exported, 1);
    const row = await db.cyrusDataRequest.findUniqueOrThrow({ where: { id: ex.id } });
    assert.equal(row.status, "ready"); assert.ok(row.archivePath && existsSync(row.archivePath));
    const zip = readFileSync(row.archivePath!);
    assert.equal(zip.readUInt32LE(0), 0x04034b50, "a zip");
    for (const name of ["README.txt", "export.json", "tables/cyrusProject.json", "tables/cyrusPersonalApiKey.json", "tables/cyrusNotificationPref.json", "tables/serverGrants.json"]) assert.ok(zip.includes(Buffer.from(name)), name);
    assert.ok(!zip.includes(Buffer.from("f".repeat(63) + "1")), "never the key hash");
    await db.cyrusDataRequest.create({ data: { userId: u.id, kind: "delete", graceUntil: new Date(Date.now() - 1000) } });
    const r2 = await dataJobsTick(dataJobDeps(env));
    assert.equal(r2.deleted, 1);
    assert.equal(await db.cyrusProject.count({ where: { userId: u.id } }), 0);
    assert.equal(await db.cyrusPersonalApiKey.count({ where: { userId: u.id } }), 0);
    assert.equal(existsSync(row.archivePath!), false, "archive removed with the data");
    delete process.env.CYRUS_GDPR_ERASE;
  });
});
EOF
