  refund(a: { userId: string; cents: number; description: string; reference?: string }): Promise<{ ok: true; replay?: boolean } | { ok: false; error: "invalid" }>;
  /** Referenced wallet movements since a time (reconciliation): charges are negative cents, refunds positive. */
