// r44: the read-only Cyrus summary for the MAIN Nxeon admin (app/admin/page.tsx), behind CYRUS_ADMIN_SUMMARY=1.
// Every figure is a real count/sum over Cyrus tables (cyrusDb); a source that cannot be read is null ("–"), never 0.
// SERVER ONLY. HOST SEAM: Cyrus tables only.
import { cyrusDb } from "../db";
import { revenueFromLedger } from "./ops";
import { sqlOutboxAdmin } from "./reconcile";

const DAY = 86_400_000;
export type CyrusAdminSummary = {
  queue: { queued: number; running: number; oldestQueuedAt: Date | null } | null;
  builds7d: { succeeded: number; failed: number; successRate: number | null } | null;
  money7d: { revenueCents: number; testCents: number; spendUsd: number } | null;
  moderation: { held: number; openLibraryReports: number; openModReports: number; openLegalCases: number } | null;
  webhooks: { tableReady: boolean; dead: number; pending: number } | null;
};

const safe = async <T>(p: () => Promise<T>): Promise<T | null> => { try { return await p(); } catch { return null; } };

export async function cyrusAdminSummary(now = new Date()): Promise<CyrusAdminSummary> {
  const since = new Date(now.getTime() - 7 * DAY);
  const [queue, builds7d, money7d, moderation, webhooks] = await Promise.all([
    safe(async () => {
      const [queued, running, oldest] = await Promise.all([
        cyrusDb.modBuild.count({ where: { status: "queued" } }),
        cyrusDb.modBuild.count({ where: { status: "running" } }),
        cyrusDb.modBuild.findFirst({ where: { status: "queued" }, orderBy: { createdAt: "asc" }, select: { createdAt: true } }),
      ]);
      return { queued, running, oldestQueuedAt: oldest?.createdAt ?? null };
    }),
    safe(async () => {
      const [succeeded, failed] = await Promise.all([
        cyrusDb.modBuild.count({ where: { status: "succeeded", createdAt: { gte: since } } }),
        cyrusDb.modBuild.count({ where: { status: "failed", createdAt: { gte: since } } }),
      ]);
      return { succeeded, failed, successRate: succeeded + failed ? succeeded / (succeeded + failed) : null };
    }),
    safe(async () => {
      const [rows, cost] = await Promise.all([
        cyrusDb.cyrusTokenLedger.findMany({ where: { kind: "purchase", createdAt: { gte: since } }, select: { kind: true, source: true, meta: true }, take: 20000 }),
        cyrusDb.modBuild.aggregate({ where: { createdAt: { gte: since } }, _sum: { costUsd: true } }),
      ]);
      const r = revenueFromLedger(rows);
      return { revenueCents: r.totalCents, testCents: r.testCents, spendUsd: Number(cost._sum.costUsd ?? 0) };
    }),
    safe(async () => {
      const [held, openLibraryReports, openModReports, openLegalCases] = await Promise.all([
        cyrusDb.cyrusCatalogEntry.count({ where: { status: "held" } }),
        cyrusDb.cyrusLibraryReport.count({ where: { status: "open" } }),
        cyrusDb.cyrusModReport.count({ where: { resolvedAt: null } }),
        cyrusDb.cyrusLegalCase.count({ where: { status: { notIn: ["closed", "restored"] } } }),
      ]);
      return { held, openLibraryReports, openModReports, openLegalCases };
    }),
    safe(async () => {
      const ob = sqlOutboxAdmin(cyrusDb);
      if (!(await ob.available())) return { tableReady: false, dead: 0, pending: 0 };
      const c = await ob.counts();
      return { tableReady: true, dead: c.dead ?? 0, pending: c.pending ?? 0 };
    }),
  ]);
  return { queue, builds7d, money7d, moderation, webhooks };
}

export const cyrusAdminSummaryEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_ADMIN_SUMMARY === "1";
