  const tiles: { label: string; value: string; sub: string; href: string; tone?: "warn" | "alert" }[] = [
    { label: "Build queue", value: s.queue ? `${n(s.queue.running)} running` : "–", sub: s.queue ? `${n(s.queue.queued)} queued${s.queue.oldestQueuedAt ? ` · oldest ${Math.round((Date.now() - s.queue.oldestQueuedAt.getTime()) / 60_000)} min` : ""}` : "unreadable", href: "/admin/cyrus/builds",
