      tone: s.money7d && s.money7d.revenueCents / 100 < s.money7d.spendUsd ? "alert" : undefined },
    { label: "Holds + takedowns open", value: s.moderation ? n(s.moderation.held + s.moderation.openLegalCases) : "–", sub: s.moderation ? `${n(s.moderation.held)} held · ${n(s.moderation.openLegalCases)} legal · ${n(s.moderation.openLibraryReports + s.moderation.openModReports)} reports` : "unreadable", href: "/admin/cyrus/library",
      tone: s.moderation && s.moderation.openLegalCases > 0 ? "warn" : undefined },
    { label: "Webhook failures", value: s.webhooks ? (s.webhooks.tableReady ? n(s.webhooks.dead) : "–") : "–", sub: s.webhooks ? (s.webhooks.tableReady ? `dead · ${n(s.webhooks.pending)} pending` : "outbox table not created") : "unreadable", href: "/admin/cyrus/reconcile",
      tone: s.webhooks?.dead ? "alert" : undefined },
  ];
  return (
