          <Link key={t.label} href={t.href} className="block rounded-xl border px-3 py-2.5 transition hover:opacity-90" style={{ borderColor: t.tone === "alert" ? "rgba(248,113,113,.45)" : t.tone === "warn" ? "rgba(251,191,36,.4)" : "var(--adm-line, rgba(255,255,255,.08))" }}>
            <div className="text-[11px] font-medium uppercase tracking-wide" style={{ color: "var(--adm-mute, #94a3b8)" }}>{t.label}</div>
            <div className="mt-1 text-lg font-semibold tabular-nums" style={{ color: "var(--adm-ink, inherit)" }}>{t.value}</div>
            <div className="mt-0.5 truncate text-[12px]" style={{ color: "var(--adm-mute, #94a3b8)" }}>{t.sub}</div>
          </Link>
        ))}
      </div>
    </Panel>
  );
}

export async function CyrusSummaryCard() {
  return <CyrusSummaryView s={await cyrusAdminSummary()} />;
}
