cd /tank/dev-worktrees/cyrus-r44; sed -i 's|^    this.closed = false;$|    this.closed = false;\n    this._ping = null; // r44 keepalive timer|' scripts/console-proxy.mjs; sed -n 125,145p "app/api/console/[serverId]/route.ts"; cat > test/ws-keepalive.test.ts <<'EOF'
// r44: WebSocket keepalive pings (Cloudflare drops idle proxied sockets at ~100 s). terminal-server/keepalive.ts with
// the real `ws` library, and scripts/console-proxy.mjs as a real child process: pings when configured, none when unset,
// and no data frames either way (zero behaviour change otherwise).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import net from "node:net";
import { createHash, randomBytes } from "node:crypto";
import { once } from "node:events";
import { WebSocketServer, WebSocket } from "ws";
import { EncryptJWT } from "jose";
import { startKeepalive, wsPingIntervalMs } from "../terminal-server/keepalive";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

describe("terminal-server keepalive", () => {
  it("interval parsing: off unless 1000-90000 ms; the specific name wins over WS_KEEPALIVE_MS", () => {
    assert.equal(wsPingIntervalMs({}, "TERMINAL_WS_PING_MS"), 0);
    assert.equal(wsPingIntervalMs({ TERMINAL_WS_PING_MS: "30000" }, "TERMINAL_WS_PING_MS"), 30000);
    assert.equal(wsPingIntervalMs({ WS_KEEPALIVE_MS: "25000" }, "TERMINAL_WS_PING_MS"), 25000);
    for (const bad of ["0", "500", "120000", "abc", "30000.5"]) assert.equal(wsPingIntervalMs({ TERMINAL_WS_PING_MS: bad }, "TERMINAL_WS_PING_MS"), 0, bad);
  });
  for (const interval of [60, 0]) {
    it(`real ws: ${interval ? "pings arrive, no data frames" : "off: no pings at all"}`, async () => {
      const wss = new WebSocketServer({ host: "127.0.0.1", port: 0 });
      await once(wss, "listening");
      let stop = () => {};
      wss.on("connection", (ws) => { stop = startKeepalive({ intervalMs: interval, isOpen: () => ws.readyState === WebSocket.OPEN, ping: () => ws.ping() }); ws.on("close", () => stop()); });
      const c = new WebSocket(`ws://127.0.0.1:${(wss.address() as net.AddressInfo).port}`);
      let pings = 0, messages = 0;
      c.on("ping", () => pings++); c.on("message", () => messages++);
      await once(c, "open");
      await sleep(400);
      c.close(); stop(); wss.close();
      if (interval) assert.ok(pings >= 3, `pings ${pings}`); else assert.equal(pings, 0);
      assert.equal(messages, 0);
    });
  }
});

describe("console-proxy keepalive (real process)", () => {
  async function run(pingMs: string | null): Promise<{ pings: number; data: number }> {
    const secret = "k".repeat(48);
    // a "Proxmox" that accepts TCP and never finishes TLS: the browser leg stays open meanwhile (15 s connect timeout)
    const hang = net.createServer(() => {}); hang.listen(0, "127.0.0.1"); await once(hang, "listening");
    const port = 20000 + Math.floor(Math.random() * 20000);
    const env: Record<string, string> = { ...process.env as Record<string, string>, AUTH_SECRET: secret, CONSOLE_PROXY_PORT: String(port), CONSOLE_PROXY_HOST: "127.0.0.1" };
    delete env.WS_KEEPALIVE_MS;
    if (pingMs) env.CONSOLE_WS_PING_MS = pingMs; else delete env.CONSOLE_WS_PING_MS;
    const p = spawn(process.execPath, ["scripts/console-proxy.mjs"], { env, stdio: ["ignore", "pipe", "pipe"] });
    try {
      await new Promise<void>((res, rej) => { p.stdout!.on("data", (d) => { if (String(d).includes("listening")) res(); }); p.on("exit", () => rej(new Error("proxy exited"))); });
      const key = new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
      const sid = await new EncryptJWT({ apiBase: `https://127.0.0.1:${(hang.address() as net.AddressInfo).port}`, node: "n1", vmid: 100, port: 5900, vncticket: "t", tokenId: "x@pve!t", tokenSecret: "s" })
        .setProtectedHeader({ alg: "dir", enc: "A256GCM" }).setJti(randomBytes(8).toString("hex")).setExpirationTime("2m").encrypt(key);
      const s = net.connect(port, "127.0.0.1"); await once(s, "connect");
      s.write(`GET /console?sid=${sid} HTTP/1.1\r\nHost: x\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: ${randomBytes(16).toString("base64")}\r\n\r\n`);
      let buf = Buffer.alloc(0);
      s.on("data", (d) => { buf = Buffer.concat([buf, d]); });
      await sleep(2600);
      s.destroy();
      const i = buf.indexOf("\r\n\r\n");
      assert.ok(buf.subarray(0, i).toString().startsWith("HTTP/1.1 101"), buf.toString().slice(0, 80));
      let frames = buf.subarray(i + 4), pings = 0, data = 0;
      while (frames.length >= 2) { const op = frames[0] & 0x0f, len = frames[1] & 0x7f; if (op === 0x9) pings++; else if (op === 0x1 || op === 0x2) data++; frames = frames.subarray(2 + len); }
      return { pings, data };
    } finally { p.kill("SIGTERM"); hang.close(); }
  }
  it("CONSOLE_WS_PING_MS=1000: the browser leg gets ping frames while the console is quiet", async () => {
    const r = await run("1000");
    assert.ok(r.pings >= 2, `pings ${r.pings}`); assert.equal(r.data, 0);
  });
  it("unset: no pings (exactly as before)", async () => {
    const r = await run(null);
    assert.equal(r.pings, 0); assert.equal(r.data, 0);
  });
});
EOF
