import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { requireCyrusAccess, cyrusMetadata } from "@/lib/cyrus-mods/gate";
import { pageForViewer, listPageCards } from "@/lib/cyrus-mods/pages";
import { modSeo } from "@/lib/cyrus-mods/seo";
import { LdScripts, RunItBand, ModFaqSection, RelatedMods } from "@/components/marketing/cyrus/CyrusModMarketing";
import { communityForSlug } from "@/lib/cyrus-mods/social";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { currentUser } from "@/lib/auth";
import { CyrusModView } from "@/components/nx/labs/cyrus/CyrusModView";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }): Promise<Metadata> {
  const { slug } = await params;
  const user = await currentUser().catch(() => null);
  const p = await pageForViewer(slug, user).catch(() => null);
  if (!p) return cyrusMetadata("Page not found");
  const c = await communityForSlug(p.slug, user, { hasCyrus: false }).catch(() => null);
  const seo = modSeo(p, c);
  const m = await cyrusMetadata(seo.title, seo.description);
  // A private page (creator viewing it) is never indexable, launched or not.
  const open = p.visibility === "PUBLIC" && !p.hidden;
  return {
    ...m,
    ...(open ? {} : { robots: { index: false, follow: false } }),
    keywords: seo.keywords,
    alternates: { canonical: `/mods/cyrus/${p.slug}` },
    openGraph: { type: "website", title: seo.title, description: seo.description, url: seo.url, siteName: "Nxeon", images: [{ url: seo.image, alt: `${p.title}, a ${seo.game.name} plugin` }] },
    twitter: { card: "summary_large_image", title: seo.title, description: seo.description, images: [seo.image] },
  };
}

/** Public Cyrus mod page. Same content as the portal page; community posting links into the portal. */
export default async function CyrusModPublicPage({ params }: { params: Promise<{ slug: string }> }) {
  const { user } = await requireCyrusAccess();
  const { slug } = await params;
  const p = await pageForViewer(slug, user);
  if (!p) notFound();
  const mb = await modBuilderUser().catch(() => null);
  const c = await communityForSlug(p.slug, user, { hasCyrus: !!mb && mb.id === user?.id });
  const seo = modSeo(p, c);
  const related = (await listPageCards(null, { take: 7 }).catch(() => [])).filter((m) => m.slug !== p.slug).slice(0, 6);
  const indexable = p.visibility === "PUBLIC" && !p.hidden;
  return (
    <div className="mx-auto flex w-full max-w-[1240px] flex-col gap-6 px-4 py-8 sm:px-6 sm:py-10">
      {indexable && <LdScripts items={[seo.jsonLd, seo.breadcrumbs, seo.faqLd]} />}
      <CyrusModView p={p} mode="public" canFork={!!mb && (p.isCreator || (p.visibility === "PUBLIC" && !p.hidden))} signedIn={!!user} c={c} />
      <RunItBand title={p.title} game={seo.game} />
      <ModFaqSection items={seo.faq} />
      <RelatedMods cards={related} game={seo.game} />
    </div>
  );
}
