// r44: the multi-version matrix WIRED into builds (CYRUS_BUILD_MATRIX=1; off = every entry point answers "off" and
// nothing is stored). A finished build can be ported to more Minecraft versions: planMatrix (r35) decides which are
// buildable, then ONE port build at a time is started through the normal build path (host.builds.create: same plan,
// token, rate and safety gates; each port is a change build of the root with the target version), and each row keeps
// its own result: build id, jar sha256, error, and the Test Flight the gate stored on that build. Stored on the root
// build's Cyrus metadata under "matrix" ({ record, done, userId }). The worker advances it (one step per tick).
// HOST SEAM: builds through the host, rows through cyrusDb.
import { cyrusDb } from "../db";
import { getHost } from "../host";
import { readStoredFlight } from "../testflight/gate";
import { matrixOn, matrixSummary, newMatrixRecord, planMatrix, MAX_MATRIX, type FlightOutcome, type MatrixRecord } from "./index";

export type StoredMatrix = { record: MatrixRecord; done: boolean; userId: string };
export type BuildFacts = { status: string; jarSha256: string | null; error: string | null; flight: FlightOutcome | null };
export type StepDeps = {
  start(version: string): Promise<{ ok: true; buildId: string } | { ok: false; error: string }>;
  facts(buildId: string): Promise<BuildFacts | null>;
};

export const PORT_REQUEST = (v: string) => `Port this plugin to Minecraft ${v}. Keep the behaviour, commands, permissions, config and assets exactly the same; change only what ${v} requires.`;
const TERMINAL = new Set(["refused", "built", "failed"]);
export const matrixFinished = (r: MatrixRecord) => r.rows.every((x) => TERMINAL.has(x.status) && (x.status !== "built" || x.testFlight.status !== "not_run" || !x.plan?.testFlight));

export function flightOf(raw: unknown): FlightOutcome | null {
  const f = readStoredFlight(raw);
  if (!f) return null;
  if (f.state === "queued" || f.state === "running") return { status: "busy", runId: f.runId ?? null };
  if (f.state === "not_run" || f.state === "gave_up") return { status: "incomplete", runId: f.runId ?? null, line: f.state };
  const v = String(f.verdict);
  return { status: v === "passed" ? "passed" : v === "failed" ? "failed" : "incomplete", runId: f.runId ?? null, line: f.label ?? undefined };
}

/** One step: settle the row being built, else start the next queued one; refresh flights of built rows. Pure over deps. */
export async function advanceMatrix(rec: MatrixRecord, deps: StepDeps): Promise<{ record: MatrixRecord; changed: boolean }> {
  const r: MatrixRecord = { ...rec, rows: rec.rows.map((x) => ({ ...x, testFlight: { ...x.testFlight } })) };
  let changed = false;
  for (const row of r.rows) {
    if (row.status !== "built" || !row.buildId || !row.plan?.testFlight || (row.testFlight.status !== "not_run" && row.testFlight.status !== "busy")) continue;
    const f = (await deps.facts(row.buildId).catch(() => null))?.flight;
    if (f && (f.status !== row.testFlight.status)) { row.testFlight = f; changed = true; }
  }
  const active = r.rows.find((x) => x.status === "building");
  if (active) {
    const f = active.buildId ? await deps.facts(active.buildId).catch(() => null) : null;
    if (!f) { active.status = "failed"; active.error = "the port build disappeared"; return { record: r, changed: true }; }
    if (f.status === "succeeded") { active.status = "built"; active.jarSha256 = f.jarSha256 ?? undefined; active.testFlight = f.flight ?? { status: "not_run", line: "waiting for the Test Flight gate" }; return { record: r, changed: true }; }
    if (f.status === "failed") { active.status = "failed"; active.error = (f.error ?? "the build failed").slice(0, 300); return { record: r, changed: true }; }
    return { record: r, changed };
  }
  const next = r.rows.find((x) => x.status === "queued");
  if (!next) return { record: r, changed };
  const s = await deps.start(next.version).catch((e) => ({ ok: false as const, error: String((e as Error)?.message ?? e) }));
  if (s.ok) { next.status = "building"; next.buildId = s.buildId; } else { next.status = "failed"; next.error = s.error.slice(0, 300); }
  return { record: r, changed: true };
}

type Root = { id: string; userId: string; status: string; mcVersion: string; prompt: string; jarSha256: string | null; cyrus: unknown };

/** Plan + store a matrix on a finished root build. The root's own version is reused as its row (never rebuilt). */
export async function startBuildMatrix(root: Root, versions: unknown, env: Record<string, string | undefined> = process.env): Promise<{ ok: true; matrix: StoredMatrix } | { ok: false; status: number; error: string }> {
  if (!matrixOn(env)) return { ok: false, status: 404, error: "not found" };
  if (root.status !== "succeeded") return { ok: false, status: 409, error: "Only a finished build can be built for more versions." };
  const prev = (root.cyrus as { matrix?: StoredMatrix } | null)?.matrix;
  if (prev && !prev.done) return { ok: false, status: 409, error: "A multi-version build is already running for this mod." };
  const list = Array.isArray(versions) ? [...new Set(versions.map(String))].slice(0, MAX_MATRIX) : [];
  if (!list.length) return { ok: false, status: 400, error: "Pick at least one Minecraft version." };
  const plan = planMatrix(list);
  if (!plan.ok) return { ok: false, status: 400, error: plan.error };
  const rec = newMatrixRecord({ rootBuildId: root.id, prompt: root.prompt }, plan.rows);
  for (const row of rec.rows) if (row.version === root.mcVersion && row.status === "queued") {
    row.status = "built"; row.buildId = root.id; row.jarSha256 = root.jarSha256 ?? undefined;
    row.testFlight = flightOf((root.cyrus as { testFlight?: unknown } | null)?.testFlight) ?? { status: "not_run", line: "waiting for the Test Flight gate" };
  }
  const matrix: StoredMatrix = { record: rec, done: matrixFinished(rec), userId: root.userId };
  await getHost().builds.mergeCyrusKey(root.id, "matrix", matrix);
  return { ok: true, matrix };
}

export const matrixView = (m: StoredMatrix) => ({ ...m.record, done: m.done, summary: matrixSummary(m.record).line });

/** Worker tick: advance every unfinished matrix by one step (inert while off). */
export async function buildMatrixSweep(env: Record<string, string | undefined> = process.env): Promise<{ advanced: number }> {
  if (!matrixOn(env)) return { advanced: 0 };
  const roots = await cyrusDb.modBuild.findMany({ where: { cyrus: { path: ["matrix", "done"], equals: false } }, select: { id: true, userId: true, cyrus: true }, take: 20 });
  let advanced = 0;
  for (const root of roots) {
    const m = (root.cyrus as { matrix?: StoredMatrix }).matrix;
    if (!m) continue;
    const user = await getHost().builds.accountFor(m.userId).catch(() => null);
    const deps: StepDeps = {
      async start(version) {
        if (!user) return { ok: false, error: "this account cannot build right now" };
        const r = await getHost().builds.create(user, { baseBuildId: root.id, mcVersion: version, changeRequest: PORT_REQUEST(version) });
        const id = (r as { body?: { build?: { id?: string } } }).body?.build?.id;
        return r.status < 300 && id ? { ok: true, buildId: id } : { ok: false, error: String((r as { body?: { error?: string } }).body?.error ?? `could not start (${r.status})`) };
      },
      async facts(buildId) {
        const b = await cyrusDb.modBuild.findUnique({ where: { id: buildId }, select: { status: true, jarSha256: true, error: true, userId: true, cyrus: true } });
        if (!b || b.userId !== m.userId) return null;
        return { status: b.status, jarSha256: b.jarSha256, error: b.error, flight: flightOf((b.cyrus as { testFlight?: unknown } | null)?.testFlight) };
      },
    };
    const step = await advanceMatrix(m.record, deps);
    if (!step.changed) continue;
    await getHost().builds.mergeCyrusKey(root.id, "matrix", { ...m, record: step.record, done: matrixFinished(step.record) } satisfies StoredMatrix);
    advanced++;
  }
  return { advanced };
}
EOF
