import { NOT_FOUND, ownedBuild } from "../../../_lib";

export const dynamic = "force-dynamic";

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  if (!matrixOn()) return NOT_FOUND();
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const m = (o.build.cyrus as { matrix?: StoredMatrix } | null)?.matrix;
  return NextResponse.json({ matrix: m ? matrixView(m) : null }, { headers: { "Cache-Control": "no-store" } });
}

export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  if (!matrixOn()) return NOT_FOUND();
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  if (!checkRateLimit(`cyrus:matrix:${o.build.userId}`, { max: 4, windowMs: 60_000 }).ok) return NextResponse.json({ error: "Too many tries." }, { status: 429 });
  const body = (await req.json().catch(() => ({}))) as { versions?: unknown };
  const r = await startBuildMatrix(o.build, body.versions);
  if (!r.ok) return r.status === 404 ? NOT_FOUND() : NextResponse.json({ error: r.error }, { status: r.status });
  return NextResponse.json({ matrix: matrixView(r.matrix) }, { status: 202 });
}
