// "Use in project": library asset -> a ModSpec asset slot { source: "library", libraryRef: "cat:<sha256>" } plus the
// project's OWN copy of the bytes, and the build-time resolver that keeps existing mods working.
//   useCatalogAsset()      a NEW pick: published only, the plan gate (canAsset create: sounds Saka+, visuals the top
//                          "All models" plan, free/Katara nothing), the licence tiers per plan and the proprietary
//                          clearance (resolveLibrarySlot of the catalog tools). The bytes are copied into the project
//                          (ProjectAssetSink -> CyrusProjectAsset in Nxeon); the owner's proprietary sounds are never
//                          copied raw: they stay a library render (layer `lib:<id>`, transformed at build time).
//                          The use is recorded (LibraryRecords.uses) so a takedown can mark its dependents.
//   resolveSlotForBuild()  what a build runs per library slot. A slot the project already holds a copy of is resolved
//                          from THAT copy, with NO plan gate and whatever the library status is now (keeping,
//                          installing, rebuilding and exporting are never gated; a removed asset keeps working in mods
//                          that already used it, with a notice). Only a slot without a copy is a new pick (gated).
// HOST SEAM: no Nxeon imports; the sink and the uses store are injected.
import { SLOT_ID_RE, type AssetSlot } from "../../engine-core/spec";
import { CATALOG_REF_RE, catalogRef, gateKindOf, type CatalogEntry } from "../v2/entry";
import type { CatalogIndex } from "../v2/retrieval";
import { resolveLibrarySlot, type SlotDecision, type ToolContext } from "../v2/tools";
import { isFolderEntry } from "./derive";
import type { LibraryStore } from "./library-store";
import type { LibraryRecords, UseRow } from "./records";

export interface ProjectAssetSink {
  /** store the project's own copy; idempotent per (project, slot, sha256) */
  put(a: { projectId: string; slotId: string; kind: AssetSlot["kind"]; bytes: Uint8Array; mime: string; provenance: Record<string, unknown> }): Promise<{ sha256: string; path: string | null }>;
}

export type UseInput = { ref: string; projectId: string; slotId: string; purpose?: string; requirementIds?: string[]; plan: unknown; proprietaryCleared: boolean; game: string | null };
export type UseOk = { ok: true; slot: AssetSlot; use: UseRow; copy: { sha256: string; path: string | null } | null; transform: string[]; reused: boolean; rule: string | null };
export type UseFail = { ok: false; code: Extract<SlotDecision, { ok: false }>["code"] | "bad_request" | "bytes_unavailable"; reason: string };
export type UseDeps = { index: CatalogIndex; store: LibraryStore; uses: LibraryRecords["uses"]; sink: ProjectAssetSink; now: () => Date };

const PROJECT_RE = /^[A-Za-z0-9_-]{4,64}$/;
const slotFor = (e: CatalogEntry, input: UseInput): AssetSlot => ({
  id: input.slotId, kind: gateKindOf(e.kind), purpose: (input.purpose?.trim() || `${e.title} from the asset library`).slice(0, 300),
  source: "library", libraryRef: catalogRef(e.id), requirementIds: input.requirementIds ?? [],
});

export async function useCatalogAsset(input: UseInput, deps: UseDeps): Promise<UseOk | UseFail> {
  if (!CATALOG_REF_RE.test(input.ref)) return { ok: false, code: "bad_ref", reason: "ref must be cat:<sha256>" };
  if (!SLOT_ID_RE.test(input.slotId)) return { ok: false, code: "bad_request", reason: "slot ids are lowercase letters, digits and underscores" };
