// Cyrus r31: the REAL dependencies of the library browser (./browse.ts) and "Use in project". SERVER ONLY.
// Switch CYRUS_LIBRARY_BROWSE=1 (default off). Index: the backend's Postgres index when CYRUS_LIBRARY_BACKEND is on,
// else the SQLite file of CYRUS_CATALOG_INDEX (the build tools' index). "Use in project" needs the backend (bytes +
// use records) and copies the bytes into the project (./project-sink.ts); without the backend it answers 503.
import { getHost } from "../../host";
import { prismaStudioStore } from "../../studios/store-prisma";
import { libraryFlags, type Env } from "../backend/flags";
import { libraryHttpDeps } from "../backend/runtime";
import { useCatalogAsset } from "../backend/use";
import { configuredCatalogIndex } from "./build-wiring";
import { LIBRARY_BROWSE_FLAG, type BrowseDeps } from "./browse";
import { fileProjectSink } from "./project-sink";

export function browseDeps(env: Env = process.env): BrowseDeps {
  const flags = libraryFlags(env);
  const http = libraryHttpDeps(env);
  const backend = env[LIBRARY_BROWSE_FLAG] === "1" ? http.backend() : null;
  return {
    on: () => env[LIBRARY_BROWSE_FLAG] === "1",
    viewer: http.viewer,
    planOf: http.planOf,
    index: async () => backend?.index ?? configuredCatalogIndex(),
    proprietaryCleared: flags.proprietaryCleared,
    ownsProject: async (userId, projectId) => { const p = await prismaStudioStore.project(projectId); return !!p && p.userId === userId; },
    ...(backend ? {
      use: async (r) => {
        const out = await useCatalogAsset({ ref: r.ref, projectId: r.projectId, slotId: r.slotId, purpose: r.purpose, plan: r.plan, proprietaryCleared: flags.proprietaryCleared, game: "minecraft" },
          { index: backend.index, store: backend.store, uses: backend.records.uses, sink: fileProjectSink(prismaStudioStore), now: () => new Date() });
        return out.ok ? { ok: true as const, slot: out.slot, copied: !!out.copy, reused: out.reused, rule: out.rule } : { ok: false as const, code: out.code, reason: out.reason };
      },
    } : {}),
    rateLimit: (key, max, windowMs) => getHost().rateLimit.check(key, { max, windowMs }),
  };
}
