// Cyrus asset library backend against a THROWAWAY Postgres (node-2 agent cluster): the Postgres catalog (store of
// record + posting index) ranks exactly like the memory index, a re-upsert writes nothing, the records (derivatives,
// uses, reports, moderation log, fingerprints) round-trip, contribution -> report -> takedown -> the dependent mod
// keeps building, the pg_trgm typo fallback and the full-text admin find.
// Opt-in and fail-closed: runs only when CYRUS_LIBRARY_BACKEND_DB_TEST=1 and DATABASE_URL is a node-2 agent database.
//   devhost db push && devhost run --lock -- env CYRUS_LIBRARY_BACKEND_DB_TEST=1 npx tsx --test test/cyrus-library-backend-db.test.ts
// It EMPTIES the r26 library tables of that throwaway database first (never anything else).
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { PrismaClient } from "@prisma/client";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { createMemoryCatalogIndex, type CatalogQuery } from "../lib/cyrus/library/v2/retrieval";
import { ingestRows } from "../lib/cyrus/library/v2/pipeline";
import type { CatalogEntry } from "../lib/cyrus/library/v2/entry";
import { createPgCatalog, prismaSql, type PgCatalog } from "../lib/cyrus/library/backend/pg";
import { PG_EXTRAS_SQL } from "../lib/cyrus/library/backend/pg-extras";
import { createMemoryLibraryObjectStore } from "../lib/cyrus/library/backend/objects";
import { encodeRgbaPng } from "../lib/cyrus/library/backend/derive";
import { LibraryStore } from "../lib/cyrus/library/backend/library-store";
import { contributeAsset } from "../lib/cyrus/library/backend/contribute";
import { report, takedown } from "../lib/cyrus/library/backend/moderation";
import { createMemoryProjectSink, resolveSlotForBuild, useCatalogAsset } from "../lib/cyrus/library/backend/use";
import { loadGoldenSample } from "./_cyrus-catalog-golden";
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_LIBRARY_BACKEND_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_LIBRARY_BACKEND_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";
const NOW = new Date("2026-10-10T12:00:00Z");
const TABLES = ["CyrusCatalogEntry", "CyrusCatalogTerm", "CyrusLibraryDerivative", "CyrusLibraryUse", "CyrusLibraryReport", "CyrusLibraryModeration", "CyrusLibraryFingerprint"];
let prisma: PrismaClient;
let pg: PgCatalog;
let entries: CatalogEntry[] = [];
before(async () => {
  if (!safe) return;
  prisma = new PrismaClient();
  for (const s of PG_EXTRAS_SQL) await prisma.$executeRawUnsafe(s);
  for (const t of TABLES) await prisma.$executeRawUnsafe(`DELETE FROM "${t}"`);
  pg = createPgCatalog(prismaSql(prisma), { fuzzy: true, now: () => NOW, batch: 64 });
  const g = loadGoldenSample();
  entries = (await ingestRows(g.rows, { profiles: [minecraftAssetProfile], packs: g.packs, now: "2026-10-10T00:00:00Z" })).entries;
});
after(async () => { if (safe) { for (const t of TABLES) await prisma.$executeRawUnsafe(`DELETE FROM "${t}"`); await prisma.$disconnect(); } });
  it("contribution -> report -> takedown -> the mod that used it keeps building from its copy", async () => {
    const objects = createMemoryLibraryObjectStore();
    const store = new LibraryStore({ objects, staging: null, records: pg.records, tools: { ffmpeg: null, python: null, gltfTransform: null, run: () => ({ status: 1, stdout: Buffer.alloc(0), stderr: "" }) }, now: () => NOW });
    const px = new Uint8ClampedArray(16 * 16 * 4).map((_, i) => (i % 4 === 3 ? 255 : (i * 29) % 256));
    const bytes = encodeRgbaPng(16, 16, px);
    const c = await contributeAsset({ studio: "texture", kind: "sprite", format: "png", bytes, name: "db test gem", manifest: { legalClass: "user-original", provenance: { source: "user", derivedFrom: [] } }, contributorId: "ctr_dbtest" },
      { enabled: true, catalog: pg.store, index: pg.index, objects, records: pg.records, profiles: [minecraftAssetProfile], now: () => NOW });
    assert.equal(c.outcome, "published");
    const id = createHash("sha256").update(bytes).digest("hex");
    assert.equal((await pg.records.fingerprints.candidates("sprite", "dhash64", (await prisma.$queryRawUnsafe<{ fp: string }[]>(`SELECT fp FROM "CyrusLibraryFingerprint" WHERE "entryId" = $1`, id))[0].fp)).length, 1);
    const thumb = await store.derivative((await pg.store.getMany([id]))[0], "thumb@1");
    assert.ok(thumb.ok);
    assert.equal((await pg.records.derivatives.get(id, "thumb@1"))?.bytes, thumb.ok ? thumb.bytes.length : -1);
    const used = await useCatalogAsset({ ref: `cat:${id}`, projectId: "proj_db", slotId: "gem", plan: "all", proprietaryCleared: false, game: null }, { index: pg.index, store, uses: pg.records.uses, sink: createMemoryProjectSink(), now: () => NOW });
    assert.ok(used.ok);
    const md = { catalog: pg.store, index: pg.index, records: pg.records, store, now: () => NOW };
    const rep = await report(md, { entryId: id, reporter: "u:dbtest", reason: "copyright" });
    assert.ok(rep.ok && rep.held);
    const td = await takedown(md, { entryId: id, by: "owner:test", reason: "copyright claim", legal: true });
    assert.ok(td.ok && td.dependents === 1 && td.purged === 1);
    assert.equal((await pg.records.uses.get("proj_db", "gem"))?.upstream, "removed");
    const keep = await resolveSlotForBuild({ id: "gem", kind: "texture", source: "library", libraryRef: `cat:${id}` }, { index: pg.index, plan: "free", game: null, proprietaryCleared: false, projectId: "proj_db", uses: pg.records.uses });
    assert.ok(keep.ok && keep.from === "project-copy");
    const log = await pg.records.log.list({ entryId: id });
    assert.deepEqual(log.map((r) => r.action).sort(), ["contribute", "hold", "report", "takedown"]); // same timestamp: order by id is arbitrary
    assert.equal((await pg.admin.counts()).find((r) => r.tier === "user-contributed")?.status, "removed");
  });
});

