describe("r44 multi-version builds wired (advanceMatrix)", () => {
  it("one port at a time; each row keeps its own build, jar, error and Test Flight; root version reused", async () => {
    const { advanceMatrix, matrixFinished, flightOf, startBuildMatrix } = await import("../lib/cyrus/matrix/wire");
    const { newMatrixRecord, planMatrix } = await import("../lib/cyrus/matrix");
    const plan = planMatrix(["1.21.4", "1.21.8", "1.21.11"]);
    assert.ok(plan.ok);
    const rec = newMatrixRecord({ x: 1 }, plan.rows);
    const builds: Record<string, { status: string; jarSha256: string | null; error: string | null; flight: any }> = {};
    let n = 0; const started: string[] = [];
    const deps = {
      async start(v: string) { started.push(v); const id = `b${++n}`; builds[id] = { status: "running", jarSha256: null, error: null, flight: null }; return v === "1.21.8" ? { ok: false as const, error: "insufficient tokens" } : { ok: true as const, buildId: id }; },
      async facts(id: string) { return builds[id] ?? null; },
    };
    let r = (await advanceMatrix(rec, deps)).record;
    assert.deepEqual(started, ["1.21.4"]); assert.equal(r.rows.filter((x) => x.status === "building").length, 1);
    r = (await advanceMatrix(r, deps)).record; assert.deepEqual(started, ["1.21.4"], "never two at once");
    builds.b1 = { status: "succeeded", jarSha256: "a".repeat(64), error: null, flight: null };
    r = (await advanceMatrix(r, deps)).record;
    assert.equal(r.rows[0].status, "built"); assert.equal(r.rows[0].jarSha256, "a".repeat(64));
    r = (await advanceMatrix(r, deps)).record; // starts 1.21.8 -> refused by the gate
    assert.equal(r.rows[1].status, "failed"); assert.equal(r.rows[1].error, "insufficient tokens");
    r = (await advanceMatrix(r, deps)).record; // 1.21.11
    builds.b3 = { status: "failed", jarSha256: null, error: "compile error", flight: null };
    r = (await advanceMatrix(r, deps)).record;
    assert.equal(r.rows[2].status, "failed");
    builds.b1.flight = { status: "passed", runId: "tf1" };
    r = (await advanceMatrix(r, deps)).record;
    assert.equal(r.rows[0].testFlight.status, "passed");
    assert.equal(matrixFinished(r), true);
    assert.equal(flightOf({ schema: 1, state: "done", verdict: "passed", checks: [], label: "boot-tested on Paper 1.21.4" })?.status, "passed");
    assert.equal(flightOf(null), null);
    const off = await startBuildMatrix({ id: "b", userId: "u", status: "succeeded", mcVersion: "1.21.11", prompt: "p", jarSha256: null, cyrus: null }, ["1.21.4"], {});
    assert.equal(off.ok, false); assert.equal((off as any).status, 404, "flag off = 404, nothing stored");
  });
});

describe("r44 Try It + evidence badges placement", () => {
  it("Try It sits under the build header, renders nothing until the API answers; badges load only behind the pass-rate switch", async () => {
    const { readFileSync } = await import("node:fs");
    const panel = readFileSync(new URL("../components/cyrus/preview/PreviewPanel.tsx", import.meta.url), "utf8");
    assert.match(panel, /realV && builtOk && !streaming && <TryItButton buildId=\{realV\.buildId\}/);
    const btn = readFileSync(new URL("../components/cyrus/TryItButton.tsx", import.meta.url), "utf8");
    assert.match(btn, /if \(off \|\| !ready\) return null;/);
    for (const f of ["../app/(marketing)/mods/cyrus/[slug]/page.tsx", "../app/dashboard/nxlabs/cyrus/[slug]/page.tsx"]) assert.match(readFileSync(new URL(f, import.meta.url), "utf8"), /modPageBadges\(p\.doc\.currentBuildId\)/);
    const data = readFileSync(new URL("../lib/cyrus/eval/passrate-data.ts", import.meta.url), "utf8");
    assert.match(data, /if \(!buildId \|\| !\(await passRateEnabled\(\)\)\) return \[\];/);
  });
});
