  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: false, timeout: 120000 }).catch((e) => errs.push("shot " + String(e).slice(0, 120)));
  console.log(`${name}.png`, res ? res.status() : "-", overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
